module.exports = {
 "admin/advisers.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n<%- include('../partials/admin_navbar') %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <h4 class=\"page-title mb-1\">Advisers</h4>\n    <p class=\"page-subtitle\">Designate the advisory class per section. Its teacher is the section adviser - the only one who can print the students' SF9.</p>\n    <% if (!years.length) { %>\n        <div class=\"alert alert-info\">No academic years yet.</div>\n    <% } else { %>\n    <form method=\"GET\" class=\"mb-2\">\n        <input type=\"hidden\" name=\"page\" value=\"advisers\">\n        <select name=\"year\" class=\"form-select form-select-sm\" style=\"width:auto;\" onchange=\"this.form.submit()\">\n            <% for (const y of years) { %>\n                <option value=\"<%= y.id %>\" <%= Number(y.id) === Number(year_id) ? 'selected' : '' %>>SY <%= y.label %></option>\n            <% } %>\n        </select>\n    </form>\n    <% if (!sections.length) { %>\n        <div class=\"alert alert-info\">No classes for SY <%= year_label %> yet.</div>\n    <% } else { %>\n    <div class=\"row g-3\">\n        <% for (const sec of sections) { %>\n            <div class=\"col-md-6 col-xl-4\">\n                <div class=\"card shadow-sm h-100\">\n                    <div class=\"card-header d-flex justify-content-between align-items-center\">\n                        <strong><%= sec.section %></strong>\n                        <% if (sec.has_adviser) { %>\n                            <span class=\"badge bg-success\">Adviser set</span>\n                        <% } else { %>\n                            <span class=\"badge bg-secondary\">No adviser</span>\n                        <% } %>\n                    </div>\n                    <ul class=\"list-group list-group-flush\">\n                        <% for (const r of sec.classes) { %>\n                            <li class=\"list-group-item d-flex justify-content-between align-items-center\">\n                                <div>\n                                    <div class=\"fw-semibold small\"><%= r.subject %></div>\n                                    <small class=\"text-muted\"><%= r.teacher !== '' ? r.teacher : 'Teacher TBA' %> &middot; <%= Number(r.students) %> students</small>\n                                </div>\n                                <form method=\"POST\">\n                                    <%- csrf_field %>\n                                    <input type=\"hidden\" name=\"action\" value=\"toggle_advisory\">\n                                    <input type=\"hidden\" name=\"class_id\" value=\"<%= r.id %>\">\n                                    <button type=\"submit\" class=\"btn btn-sm <%= Number(r.is_advisory) ? 'btn-outline-danger' : 'btn-brand' %>\">\n                                        <%= Number(r.is_advisory) ? 'Remove adviser' : 'Set as advisory' %>\n                                    </button>\n                                </form>\n                            </li>\n                        <% } %>\n                    </ul>\n                </div>\n            </div>\n        <% } %>\n    </div>\n    <% } %>\n    <% } %>\n\n</div>\n\n<%- include('../partials/admin_footer') %>\n</body>\n</html>\n",
 "admin/announcements.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n<%- include('../partials/admin_navbar') %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <h4 class=\"page-title mb-1\">School Announcements</h4>\n    <div class=\"row g-3\">\n        <div class=\"col-md-4\">\n            <div class=\"card shadow-sm\"><div class=\"card-header fw-semibold\">Post Announcement</div><div class=\"card-body\">\n                <form method=\"POST\">\n                    <input type=\"hidden\" name=\"action\" value=\"add_school_ann\">\n                    <div class=\"mb-2\"><input type=\"text\" name=\"title\" class=\"form-control\" placeholder=\"Title\" required></div>\n                    <div class=\"mb-2\"><textarea name=\"content\" class=\"form-control\" rows=\"4\" placeholder=\"Content\" required></textarea></div>\n                    <div class=\"mb-2\">\n                        <select name=\"audience\" class=\"form-select\">\n                            <option value=\"all\">Everyone</option>\n                            <option value=\"students\">Students only</option>\n                            <option value=\"teachers\">Teachers only</option>\n                        </select>\n                    </div>\n                    <button type=\"submit\" class=\"btn btn-sm btn-brand\">Post</button>\n                </form>\n            </div></div>\n        </div>\n        <div class=\"col-md-8\">\n            <% if (!list.length) { %>\n                <div class=\"alert alert-info\">No announcements yet.</div>\n            <% } else { %>\n                <div class=\"list-group\">\n                <% for (const a of list) { %>\n                    <div class=\"list-group-item\"><div class=\"d-flex justify-content-between\"><div><div class=\"fw-semibold\"><%= a.title %> <span class=\"badge bg-secondary\"><%= a.audience %></span></div>\n                    <small><%- h.esc(a.content).replace(/\\n/g, '<br />\\n') %></small><br><small class=\"text-muted\"><%= a.email ?? 'system' %> | <%= a.posted_at %></small></div>\n                    <form method=\"POST\" class=\"d-inline\"><input type=\"hidden\" name=\"action\" value=\"delete_school_ann\"><input type=\"hidden\" name=\"ann_id\" value=\"<%= a.id %>\"><button type=\"submit\" class=\"btn btn-sm btn-outline-danger\">&times;</button></form></div></div>\n                <% } %>\n                </div>\n            <% } %>\n        </div>\n    </div>\n\n</div>\n\n<%- include('../partials/admin_footer') %>\n</body>\n</html>\n",
 "admin/audit.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n<%- include('../partials/admin_navbar') %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <h4 class=\"page-title mb-1\">Audit Log</h4>\n    <% if (!rows.length) { %>\n        <div class=\"alert alert-info\">No audit records yet.</div>\n    <% } else { %>\n    <div class=\"table-responsive\">\n        <table class=\"table table-sm table-striped\">\n            <thead><tr><th>#</th><th>Time</th><th>User</th><th>Action</th><th>Target</th><th>Old → New</th><th>IP</th></tr></thead>\n            <tbody>\n            <% for (const r of rows) { %>\n                <tr>\n                    <td><%= r.id %></td>\n                    <td><small><%= r.created_at %></small></td>\n                    <td><small><%= r.email ?? 'system' %></small></td>\n                    <td><code><%= r.action %></code></td>\n                    <td><small><%= r.target_type ?? '' %> <%= r.target_id ? '#' + r.target_id : '' %></small></td>\n                    <td><small><%= r.old_value ?? '' %><%= (r.old_value !== null && r.new_value !== null) ? ' → ' : '' %><%= r.new_value ?? '' %></small></td>\n                    <td><small><%= r.ip ?? '' %></small></td>\n                </tr>\n            <% } %>\n            </tbody>\n        </table>\n    </div>\n    <% } %>\n\n</div>\n\n<%- include('../partials/admin_footer') %>\n</body>\n</html>\n",
 "admin/calendar.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n<%- include('../partials/admin_navbar') %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <h4 class=\"page-title mb-1\">School Calendar</h4>\n    <div class=\"row g-3\">\n        <div class=\"col-md-4\">\n            <div class=\"card shadow-sm\"><div class=\"card-header fw-semibold\">Add Event</div><div class=\"card-body\">\n                <form method=\"POST\">\n                    <input type=\"hidden\" name=\"action\" value=\"add_event\">\n                    <div class=\"mb-2\"><label class=\"small fw-semibold\">Title</label><input type=\"text\" name=\"title\" class=\"form-control\" required></div>\n                    <div class=\"row g-2 mb-2\">\n                        <div class=\"col\"><label class=\"small fw-semibold\">Date</label><input type=\"date\" name=\"event_date\" class=\"form-control\" required></div>\n                        <div class=\"col\"><label class=\"small fw-semibold\">End (optional)</label><input type=\"date\" name=\"end_date\" class=\"form-control\"></div>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"small fw-semibold\">Type</label>\n                        <select name=\"event_type\" class=\"form-select\">\n                            <option value=\"event\">Event</option>\n                            <option value=\"holiday\">Holiday</option>\n                            <option value=\"exam\">Exam</option>\n                            <option value=\"deadline\">Deadline</option>\n                            <option value=\"term_start\">Term Start</option>\n                            <option value=\"term_end\">Term End</option>\n                            <option value=\"suspension\">Suspension</option>\n                        </select>\n                    </div>\n                    <div class=\"mb-2\">\n                        <label class=\"small fw-semibold\">Term (optional)</label>\n                        <select name=\"term_id\" class=\"form-select\">\n                            <option value=\"\">None</option>\n                            <% for (const t of terms) { %><option value=\"<%= t.id %>\"><%= t.yl %> - <%= t.label %></option><% } %>\n                        </select>\n                    </div>\n                    <div class=\"mb-2\"><label class=\"small fw-semibold\">Description</label><textarea name=\"description\" class=\"form-control\" rows=\"2\"></textarea></div>\n                    <button type=\"submit\" class=\"btn btn-sm btn-brand\">Add Event</button>\n                </form>\n            </div></div>\n        </div>\n        <div class=\"col-md-8\">\n            <div class=\"card shadow-sm\"><div class=\"card-header d-flex justify-content-between align-items-center\">\n                <form method=\"GET\" class=\"d-flex gap-1\">\n                    <input type=\"hidden\" name=\"page\" value=\"calendar\">\n                    <input type=\"month\" name=\"month\" class=\"form-control form-control-sm\" value=\"<%= month %>\">\n                    <button type=\"submit\" class=\"btn btn-sm btn-outline-primary\">Go</button>\n                </form>\n            </div><div class=\"card-body p-0\">\n            <% if (!evs.length) { %>\n                <p class=\"text-muted small p-3 mb-0\">No events this month.</p>\n            <% } else { %>\n                <ul class=\"list-group list-group-flush\">\n                <% for (const e of evs) { %>\n                    <li class=\"list-group-item d-flex justify-content-between align-items-center\"><span><span class=\"badge bg-<%= e.event_type == 'holiday' ? 'danger' : (e.event_type == 'exam' ? 'warning' : 'info') %>\"><%= e.event_type %></span> <strong><%= e.title %></strong> <small class=\"text-muted\"><%= e.event_date %><%= e.end_date ? ' → ' + e.end_date : '' %></small></span>\n                    <form method=\"POST\" class=\"d-inline\"><input type=\"hidden\" name=\"action\" value=\"delete_event\"><input type=\"hidden\" name=\"event_id\" value=\"<%= e.id %>\"><button type=\"submit\" class=\"btn btn-sm btn-outline-danger\">&times;</button></form></li>\n                <% } %>\n                </ul>\n            <% } %>\n            </div></div>\n        </div>\n    </div>\n\n</div>\n\n<%- include('../partials/admin_footer') %>\n</body>\n</html>\n",
 "admin/overview.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n<%- include('../partials/admin_navbar') %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <div class=\"page-header\">\n        <div>\n            <h4 class=\"page-title\">Admin Overview</h4>\n            <p class=\"page-subtitle\">School-wide snapshot</p>\n        </div>\n    </div>\n    <div class=\"row g-3\">\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('book', 20) %></div><p class=\"stat-value\"><%= teachers %></p><span class=\"stat-label\">Active Teachers</span></div></div>\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('users', 20) %></div><p class=\"stat-value\"><%= students %></p><span class=\"stat-label\">Active Students</span></div></div>\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('school', 20) %></div><p class=\"stat-value\"><%= classes %></p><span class=\"stat-label\">Active Classes</span></div></div>\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('award', 20) %></div><p class=\"stat-value\"><%= graded %></p><span class=\"stat-label\">Term Grades Recorded</span></div></div>\n    </div>\n    <div class=\"row g-3 mt-1\">\n        <div class=\"col-md-6\"><div class=\"card shadow-sm\"><div class=\"card-header fw-semibold\">Upcoming Events (next 30 days)</div><div class=\"card-body p-0\">\n            <% if (!evs.length) { %>\n                <p class=\"text-muted small p-3 mb-0\">No upcoming events.</p>\n            <% } else { %>\n                <ul class=\"list-group list-group-flush\">\n                <% for (const e of evs) { %>\n                    <li class=\"list-group-item d-flex justify-content-between\"><span><%= e.title %></span><small class=\"text-muted\"><%= e.event_date %></small></li>\n                <% } %>\n                </ul>\n            <% } %>\n        </div></div></div>\n        <div class=\"col-md-6\"><div class=\"card shadow-sm\"><div class=\"card-header fw-semibold\">Latest Audit Activity</div><div class=\"card-body p-0\">\n            <% if (!logs.length) { %>\n                <p class=\"text-muted small p-3 mb-0\">No activity yet.</p>\n            <% } else { %>\n                <ul class=\"list-group list-group-flush\">\n                <% for (const r of logs) { %>\n                    <li class=\"list-group-item d-flex justify-content-between\"><span><small><%= r.action %></small> <span class=\"text-muted\"><%= r.email ?? 'system' %></span></span><small class=\"text-muted\"><%= r.created_at %></small></li>\n                <% } %>\n                </ul>\n            <% } %>\n        </div></div></div>\n    </div>\n    <% if (unverified > 0) { %>\n        <div class=\"alert alert-warning mt-3\"><%= unverified %> pending account(s) await approval.</div>\n    <% } %>\n\n</div>\n\n<%- include('../partials/admin_footer') %>\n</body>\n</html>\n",
 "admin/policies.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n<%- include('../partials/admin_navbar') %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <div class=\"page-header\">\n        <div>\n            <h4 class=\"page-title\">Grading Scale</h4>\n            <p class=\"page-subtitle\">The descriptor bands used to label every Term Grade.</p>\n        </div>\n    </div>\n\n    <div class=\"card shadow-sm mb-3\">\n        <div class=\"card-body\">\n            <h6 class=\"fw-bold\">How grading works</h6>\n            <p class=\"small text-muted mb-0\">\n                Teachers enter one <strong>Term Grade</strong> per student per term &mdash; between\n                <%= tg_min %> and <%= tg_max %>. There are no categories,\n                activities or weights. The number a teacher types <em>is</em> the Term Grade, and the\n                bands below turn it into a descriptor word. The passing mark is\n                <strong><%= passing %></strong>.\n            </p>\n        </div>\n    </div>\n\n    <% if (chk > 0) { %>\n        <div class=\"alert alert-danger\">\n            A band ends below where it starts. Fix the ranges below &mdash; until then every\n            grade in that band will be labelled &ldquo;Invalid&rdquo;.\n        </div>\n    <% } %>\n    <% if (overlaps > 0) { %>\n        <div class=\"alert alert-warning\">\n            <%= overlaps %> band(s) overlap. descriptor_for() returns the first match, so an\n            overlapping range silently shadows the one below it.\n        </div>\n    <% } %>\n\n    <div class=\"card shadow-sm\">\n        <div class=\"card-header fw-semibold card-header-soft\">DO 015, s. 2026 reporting scale</div>\n        <div class=\"card-body\">\n            <form method=\"POST\">\n                <input type=\"hidden\" name=\"action\" value=\"descriptor_save\">\n                <div class=\"table-responsive\">\n                    <table class=\"table table-sm align-middle mb-3\">\n                        <thead>\n                            <tr>\n                                <th style=\"width:110px;\">From</th>\n                                <th style=\"width:110px;\">To</th>\n                                <th>Descriptor (EN)</th>\n                                <th>Descriptor (FIL)</th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                        <% for (const b of rows) { %>\n                            <tr>\n                                <td><input type=\"number\" step=\"0.01\" class=\"form-control form-control-sm\"\n                                           name=\"desc[<%= b.id %>][min]\" value=\"<%= h.trim_num(b.min_grade) %>\"></td>\n                                <td><input type=\"number\" step=\"0.01\" class=\"form-control form-control-sm\"\n                                           name=\"desc[<%= b.id %>][max]\" value=\"<%= h.trim_num(b.max_grade) %>\"></td>\n                                <td><input type=\"text\" class=\"form-control form-control-sm\"\n                                           name=\"desc[<%= b.id %>][label_en]\" value=\"<%= b.label_en %>\"></td>\n                                <td><input type=\"text\" class=\"form-control form-control-sm\"\n                                           name=\"desc[<%= b.id %>][label_fil]\" value=\"<%= b.label_fil ?? '' %>\"></td>\n                            </tr>\n                        <% } %>\n                        </tbody>\n                    </table>\n                </div>\n                <button type=\"submit\" class=\"btn btn-sm btn-brand\">Save Scale</button>\n            </form>\n        </div>\n    </div>\n\n</div>\n\n<%- include('../partials/admin_footer') %>\n</body>\n</html>\n",
 "admin/settings.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n<%- include('../partials/admin_navbar') %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <h4 class=\"page-title mb-1\">System Settings</h4>\n    <div class=\"row justify-content-center\">\n        <div class=\"col-md-6\">\n            <div class=\"card shadow-sm\"><div class=\"card-header fw-semibold\">General</div><div class=\"card-body\">\n                <form method=\"POST\">\n                    <input type=\"hidden\" name=\"action\" value=\"save_settings\">\n                    <div class=\"mb-2\"><label class=\"small fw-semibold\">School Name</label><input type=\"text\" name=\"school_name\" class=\"form-control\" value=\"<%= school_name %>\"></div>\n                    <div class=\"mb-3\">\n                        <label class=\"small fw-semibold\">Registration Mode</label>\n                        <select name=\"registration_mode\" class=\"form-select\">\n                            <option value=\"open\" <%= registration_mode == 'open' ? 'selected' : '' %>>Open (anyone can sign up)</option>\n                            <option value=\"approval\" <%= registration_mode == 'approval' ? 'selected' : '' %>>Approval required (admin enables account)</option>\n                        </select>\n                    </div>\n                    <button type=\"submit\" class=\"btn btn-sm btn-brand\">Save Settings</button>\n                </form>\n            </div></div>\n        </div>\n    </div>\n\n</div>\n\n<%- include('../partials/admin_footer') %>\n</body>\n</html>\n",
 "admin/users.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n<%- include('../partials/admin_navbar') %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <div class=\"d-flex justify-content-between align-items-center mb-3\">\n        <h4 class=\"page-title\">User Management</h4>\n        <form method=\"GET\" class=\"d-flex gap-1\">\n            <input type=\"hidden\" name=\"page\" value=\"users\">\n            <select name=\"role\" class=\"form-select form-select-sm\" onchange=\"this.form.submit()\">\n                <option value=\"all\" <%= role_filter=='all'?'selected':'' %>>All roles</option>\n                <option value=\"teacher\" <%= role_filter=='teacher'?'selected':'' %>>Teachers</option>\n                <option value=\"student\" <%= role_filter=='student'?'selected':'' %>>Students</option>\n            </select>\n        </form>\n    </div>\n    <% if (!list.length) { %>\n        <div class=\"alert alert-info\">No users found.</div>\n    <% } else { %>\n    <div class=\"table-responsive\">\n        <table class=\"table table-hover table-sm\">\n            <thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Admin</th><th></th></tr></thead>\n            <tbody>\n            <% for (const u of list) { const status_color = u.status == 'active' ? 'success' : (u.status == 'pending' ? 'warning' : 'secondary'); %>\n                <tr>\n                    <td><%= u.full_name ?? '' %> <small class=\"text-muted\">(<%= u.number ?? '-' %>)</small></td>\n                    <td><%= u.email %></td>\n                    <td><span class=\"badge bg-info\"><%= u.role %></span></td>\n                    <td><span class=\"badge bg-<%= status_color %>\"><%= u.status %></span></td>\n                    <td><%- Number(u.is_admin) ? '<span class=\"badge bg-dark\">Admin</span>' : '<span class=\"text-muted\">-</span>' %></td>\n                    <td class=\"text-nowrap\">\n                        <form method=\"POST\" class=\"d-inline\"><input type=\"hidden\" name=\"action\" value=\"user_toggle_admin\"><input type=\"hidden\" name=\"user_id\" value=\"<%= u.id %>\"><button type=\"submit\" class=\"btn btn-sm btn-outline-dark\"><%= Number(u.is_admin) ? 'Revoke Admin' : 'Make Admin' %></button></form>\n                        <form method=\"POST\" class=\"d-inline\"><input type=\"hidden\" name=\"action\" value=\"user_toggle_status\"><input type=\"hidden\" name=\"user_id\" value=\"<%= u.id %>\"><button type=\"submit\" class=\"btn btn-sm btn-outline-warning\"><%= u.status == 'active' ? 'Disable' : 'Enable' %></button></form>\n                        <button type=\"button\" class=\"btn btn-sm btn-outline-danger\" data-bs-toggle=\"modal\" data-bs-target=\"#resetModal<%= u.id %>\">Reset Pass</button>\n                        <div class=\"modal fade\" id=\"resetModal<%= u.id %>\"><div class=\"modal-dialog\"><form method=\"POST\" class=\"modal-content\">\n                            <input type=\"hidden\" name=\"action\" value=\"user_reset_password\"><input type=\"hidden\" name=\"user_id\" value=\"<%= u.id %>\">\n                            <div class=\"modal-header\"><h5 class=\"modal-title\">Reset Password for <%= u.email %></h5><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\"></button></div>\n                            <div class=\"modal-body\"><label class=\"small fw-semibold\">New Password (min 8 chars)</label><input type=\"text\" name=\"new_password\" class=\"form-control\" required></div>\n                            <div class=\"modal-footer\"><button type=\"submit\" class=\"btn btn-sm btn-brand\">Reset</button></div>\n                        </form></div></div>\n                    </td>\n                </tr>\n            <% } %>\n            </tbody>\n        </table>\n    </div>\n    <% } %>\n\n</div>\n\n<%- include('../partials/admin_footer') %>\n</body>\n</html>\n",
 "admin/years.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n<%- include('../partials/admin_navbar') %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <h4 class=\"page-title mb-1\">Academic Years &amp; Terms</h4>\n    <div class=\"row g-3\">\n        <div class=\"col-md-4\">\n            <div class=\"card shadow-sm\"><div class=\"card-header fw-semibold\">Add Academic Year</div><div class=\"card-body\">\n                <form method=\"POST\">\n                    <input type=\"hidden\" name=\"action\" value=\"add_year\">\n                    <div class=\"mb-2\"><label class=\"small fw-semibold\">Label</label><input type=\"text\" name=\"label\" class=\"form-control\" placeholder=\"e.g. 2027-2028\" required></div>\n                    <div class=\"row g-2 mb-2\">\n                        <div class=\"col\"><label class=\"small fw-semibold\">Start</label><input type=\"date\" name=\"start_date\" class=\"form-control\"></div>\n                        <div class=\"col\"><label class=\"small fw-semibold\">End</label><input type=\"date\" name=\"end_date\" class=\"form-control\"></div>\n                    </div>\n                    <button type=\"submit\" class=\"btn btn-sm btn-brand\">Add Year</button>\n                </form>\n            </div></div>\n        </div>\n        <div class=\"col-md-8\">\n            <% for (const y of years) { %>\n                <div class=\"card shadow-sm mb-3\"><div class=\"card-header d-flex justify-content-between align-items-center card-header-soft\">\n                    <span class=\"fw-bold\"><%= y.label %> <%- Number(y.is_active) ? '<span class=\"badge bg-success\">current</span>' : '' %></span>\n                    <% if (!Number(y.is_active)) { %>\n                        <form method=\"POST\" class=\"d-inline\"><input type=\"hidden\" name=\"action\" value=\"set_active_year\"><input type=\"hidden\" name=\"year_id\" value=\"<%= y.id %>\"><button type=\"submit\" class=\"btn btn-sm btn-outline-success\">Set Active</button></form>\n                    <% } %>\n                </div><div class=\"card-body\">\n                    <% if (y.terms.length) { %>\n                        <table class=\"table table-sm mb-3\"><thead><tr><th>Term</th><th>Dates</th><th>Weight</th><th>Status</th><th></th></tr></thead><tbody>\n                        <% for (const t of y.terms) { %>\n                            <tr><td><%= t.label %></td><td><small><%= t.start_date ?? '-' %> to <%= t.end_date ?? '-' %></small></td>\n                            <td><%= t.weight %></td><td><span class=\"badge bg-<%= t.status == 'open' ? 'success' : 'secondary' %>\"><%= t.status %></span></td>\n                            <td><form method=\"POST\" class=\"d-inline\"><input type=\"hidden\" name=\"action\" value=\"toggle_term_status\"><input type=\"hidden\" name=\"term_id\" value=\"<%= t.id %>\"><button type=\"submit\" class=\"btn btn-sm btn-outline-secondary\"><%= t.status == 'open' ? 'Close' : 'Open' %></button></form></td></tr>\n                        <% } %>\n                        </tbody></table>\n                    <% } %>\n                    <form method=\"POST\" class=\"row g-2 align-items-end\">\n                        <input type=\"hidden\" name=\"action\" value=\"add_term\"><input type=\"hidden\" name=\"year_id\" value=\"<%= y.id %>\">\n                        <div class=\"col-auto\"><label class=\"small fw-semibold\">New Term</label><input type=\"text\" name=\"label\" class=\"form-control form-control-sm\" placeholder=\"e.g. Term 4\" required></div>\n                        <div class=\"col-auto\"><label class=\"small fw-semibold\">Start</label><input type=\"date\" name=\"start_date\" class=\"form-control form-control-sm\"></div>\n                        <div class=\"col-auto\"><label class=\"small fw-semibold\">End</label><input type=\"date\" name=\"end_date\" class=\"form-control form-control-sm\"></div>\n                        <div class=\"col-auto\"><label class=\"small fw-semibold\">Weight</label><input type=\"number\" name=\"weight\" step=\"0.01\" value=\"1\" class=\"form-control form-control-sm\" style=\"width:70px;\"></div>\n                        <div class=\"col-auto\"><button type=\"submit\" class=\"btn btn-sm btn-outline-primary\">Add Term</button></div></form>\n                </div></div>\n            <% } %>\n        </div>\n    </div>\n\n</div>\n\n<%- include('../partials/admin_footer') %>\n</body>\n</html>\n",
 "auth/login.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/auth_head', { title: 'Login - School Portal' }) %>\n</head>\n<body class=\"auth-body\">\n<div class=\"auth-card-wrap\">\n    <div class=\"card auth-card shadow\">\n        <div class=\"auth-brand\">\n            <img src=\"logo.ico\" alt=\"School Portal\">\n            <h3>School Portal</h3>\n            <small>Sign in to your account</small>\n        </div>\n        <div class=\"card-body auth-body-card\">\n            <% if (error) { %>\n                <div class=\"alert alert-danger py-2\"><%= error %></div>\n            <% } %>\n            <form method=\"POST\">\n                <input type=\"hidden\" name=\"csrf_token\" value=\"<%= csrf %>\">\n                <div class=\"mb-3 text-start\">\n                    <label class=\"form-label\">Email</label>\n                    <input type=\"email\" name=\"email\" class=\"form-control\" placeholder=\"you@school.com\" required autocomplete=\"email\">\n                </div>\n                <div class=\"mb-4 text-start\">\n                    <label class=\"form-label\">Password</label>\n                    <input type=\"password\" name=\"password\" class=\"form-control\" placeholder=\"••••••••\" required autocomplete=\"current-password\">\n                </div>\n                <button type=\"submit\" class=\"btn btn-brand w-100 fw-semibold\">Sign In</button>\n            </form>\n            <p class=\"mt-3 mb-0 text-center small\"><a href=\"register.php\">Create an account</a></p>\n        </div>\n    </div>\n</div>\n<%- include('../partials/theme_toggle_float') %>\n<script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js\"></script>\n<script src=\"theme.js\"></script>\n</body>\n</html>\n",
 "auth/register.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/auth_head', { title: 'Register - School Portal' }) %>\n</head>\n<body class=\"auth-body\">\n<div class=\"auth-card-wrap\">\n    <div class=\"card auth-card shadow\">\n        <div class=\"auth-brand\">\n            <img src=\"logo.ico\" alt=\"School Portal\">\n            <h3>Create Account</h3>\n            <small>Register as a student</small>\n        </div>\n        <div class=\"card-body auth-body-card\">\n            <% if (error) { %>\n                <div class=\"alert alert-danger py-2\"><%= error %></div>\n            <% } %>\n            <% if (success) { %>\n                <div class=\"alert alert-success py-2\"><%= success %></div>\n            <% } %>\n            <form method=\"POST\">\n                <input type=\"hidden\" name=\"csrf_token\" value=\"<%= csrf %>\">\n                <div class=\"mb-2 text-start\">\n                    <label class=\"form-label\">Full Name</label>\n                    <input type=\"text\" name=\"full_name\" class=\"form-control\" placeholder=\"Juan Dela Cruz\" required>\n                </div>\n                <div class=\"mb-2 text-start\">\n                    <label class=\"form-label\">Email</label>\n                    <input type=\"email\" name=\"email\" class=\"form-control\" placeholder=\"you@school.com\" required autocomplete=\"email\">\n                </div>\n                <div class=\"mb-3 text-start\">\n                    <label class=\"form-label\">Student Number</label>\n                    <input type=\"text\" name=\"id_number\" class=\"form-control\" placeholder=\"e.g. 2026-00123\" required>\n                </div>\n                <div class=\"mb-4 text-start\">\n                    <label class=\"form-label\">Password (min 8 characters)</label>\n                    <input type=\"password\" name=\"password\" class=\"form-control\" placeholder=\"••••••••\" required minlength=\"8\" autocomplete=\"new-password\">\n                </div>\n                <button type=\"submit\" class=\"btn btn-brand w-100 fw-semibold\">Register</button>\n            </form>\n            <p class=\"mt-3 mb-0 text-center small\"><a href=\"login.php\">Already have an account? Sign in</a></p>\n        </div>\n    </div>\n</div>\n<%- include('../partials/theme_toggle_float') %>\n<script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js\"></script>\n<script src=\"theme.js\"></script>\n</body>\n</html>\n",
 "error_page.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('partials/app_head', { title: 'School Portal' }) %>\n</head>\n<body>\n<%- include('partials/navbar', { page: page || '', unread: (typeof unread !== 'undefined' ? unread : 0), chip_role: (typeof chip_role !== 'undefined' ? chip_role : (role === 'teacher' ? 'Teacher' : 'Student')), chip_ini: (typeof chip_ini !== 'undefined' ? chip_ini : 'U') }) %>\n<div class=\"container mt-4\">\n    <div class=\"alert alert-danger\"><%= message %></div>\n</div>\n<%- include('partials/footer') %>\n</body>\n</html>\n",
 "partials/admin_footer.ejs": "<footer class=\"text-center text-muted py-3 mt-4 border-top\">\n    <small>&copy; <%= year %> <%= school_name %>. All rights reserved.</small>\n</footer>\n\n<script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js\"></script>\n<script src=\"script.js\"></script>\n<script src=\"theme.js\"></script>\n",
 "partials/admin_navbar.ejs": "<nav class=\"navbar navbar-expand-lg navbar-dark app-navbar\">\n    <div class=\"container\">\n        <a class=\"navbar-brand fw-bold\" href=\"admin.php\"><img src=\"logo.ico\" alt=\"School Portal\" width=\"24\" height=\"24\" class=\"me-2\">Admin Panel</a>\n        <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#navbarNav\">\n            <span class=\"navbar-toggler-icon\"></span>\n        </button>\n        <div class=\"collapse navbar-collapse\" id=\"navbarNav\">\n            <ul class=\"navbar-nav ms-auto\">\n                <li class=\"nav-item\"><a class=\"nav-link <%= admin_page==='overview'?'active':'' %>\" href=\"admin.php\">Overview</a></li>\n                <li class=\"nav-item\"><a class=\"nav-link <%= admin_page==='users'?'active':'' %>\" href=\"admin.php?page=users\">Users</a></li>\n                <li class=\"nav-item\"><a class=\"nav-link <%= admin_page==='advisers'?'active':'' %>\" href=\"admin.php?page=advisers\">Advisers</a></li>\n                <li class=\"nav-item\"><a class=\"nav-link <%= admin_page==='years'?'active':'' %>\" href=\"admin.php?page=years\">Years &amp; Terms</a></li>\n                <li class=\"nav-item\"><a class=\"nav-link <%= admin_page==='policies'?'active':'' %>\" href=\"admin.php?page=policies\">Policies</a></li>\n                <li class=\"nav-item\"><a class=\"nav-link <%= admin_page==='calendar'?'active':'' %>\" href=\"admin.php?page=calendar\">Calendar</a></li>\n                <li class=\"nav-item\"><a class=\"nav-link <%= admin_page==='announcements'?'active':'' %>\" href=\"admin.php?page=announcements\">Announcements</a></li>\n                <li class=\"nav-item\"><a class=\"nav-link <%= admin_page==='audit'?'active':'' %>\" href=\"admin.php?page=audit\">Audit Log</a></li>\n                <li class=\"nav-item\"><a class=\"nav-link <%= admin_page==='settings'?'active':'' %>\" href=\"admin.php?page=settings\">Settings</a></li>\n                <li class=\"nav-item\"><a class=\"nav-link text-white-50\" href=\"dashboard.php\">Back to Portal</a></li>\n                <li class=\"nav-item d-none d-lg-flex align-items-center ms-lg-2\">\n                    <span class=\"nav-user-chip\">\n                        <span class=\"user-avatar\"><%= chip_ini %></span>\n                        <span class=\"user-meta\">\n                            <strong><%= chip_name %></strong>\n                            <small>Administrator</small>\n                        </span>\n                    </span>\n                </li>\n                <li class=\"nav-item ms-lg-1\">\n                    <form method=\"POST\" action=\"logout.php\" class=\"d-inline\">\n                        <input type=\"hidden\" name=\"csrf_token\" value=\"<%= csrf %>\">\n                        <button type=\"submit\" class=\"btn btn-sm btn-outline-light\">Logout</button>\n                    </form>\n                </li>\n                <li class=\"nav-item ms-lg-1\">\n                    <button type=\"button\" class=\"theme-toggle-btn\" data-theme-toggle aria-label=\"Switch to dark mode\">\n                        <svg data-icon=\"light\" class=\"d-none\" width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41\"/></svg>\n                        <svg data-icon=\"dark\" width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>\n                    </button>\n                </li>\n            </ul>\n        </div>\n    </div>\n</nav>\n",
 "partials/app_head.ejs": "<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title><%= title %></title>\n<link rel=\"icon\" href=\"logo.ico\" type=\"image/x-icon\">\n<meta name=\"csrf-token\" content=\"<%= csrf %>\">\n<script>(function(){var t=localStorage.getItem('theme');if(!t){t=window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';}document.documentElement.setAttribute('data-bs-theme',t);})();</script>\n<link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;600;700&display=swap\" rel=\"stylesheet\">\n<link href=\"style.css\" rel=\"stylesheet\">\n",
 "partials/auth_head.ejs": "<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title><%= title %></title>\n<link rel=\"icon\" href=\"logo.ico\" type=\"image/x-icon\">\n<script>(function(){var t=localStorage.getItem('theme');if(!t){t=window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';}document.documentElement.setAttribute('data-bs-theme',t);})();</script>\n<link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css\" rel=\"stylesheet\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;600;700&display=swap\" rel=\"stylesheet\">\n<link href=\"style.css\" rel=\"stylesheet\">\n",
 "partials/footer.ejs": "<footer class=\"text-center text-muted py-4 mt-5 border-top\">\n    <small>&copy; <%= year %> School Portal &middot; Research Student Information System. All rights reserved.</small>\n</footer>\n\n<script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js\"></script>\n<script src=\"script.js\"></script>\n<script src=\"theme.js\"></script>\n",
 "partials/navbar.ejs": "<!-- NAVBAR -->\n<nav class=\"navbar navbar-expand-lg navbar-dark app-navbar\">\n    <div class=\"container\">\n        <a class=\"navbar-brand fw-bold\" href=\"dashboard.php\"><img src=\"logo.ico\" alt=\"School Portal\" width=\"24\" height=\"24\" class=\"me-2\">School Portal</a>\n        <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#navbarNav\">\n            <span class=\"navbar-toggler-icon\"></span>\n        </button>\n        <div class=\"collapse navbar-collapse\" id=\"navbarNav\">\n            <ul class=\"navbar-nav ms-auto align-items-lg-center\">\n                <% if (is_admin) { %>\n                    <li class=\"nav-item\"><a class=\"nav-link\" href=\"admin.php\">Admin Panel</a></li>\n                <% } %>\n                <% if (role === 'teacher') { %>\n                    <li class=\"nav-item\"><a class=\"nav-link <%= page==='dashboard'?'active':'' %>\" href=\"dashboard.php\">Dashboard</a></li>\n                    <li class=\"nav-item\"><a class=\"nav-link <%= page==='profile'?'active':'' %>\" href=\"dashboard.php?page=profile\">Profile</a></li>\n                <% } else { %>\n                    <li class=\"nav-item\"><a class=\"nav-link <%= page==='dashboard'?'active':'' %>\" href=\"dashboard.php\">Dashboard</a></li>\n                    <li class=\"nav-item\"><a class=\"nav-link <%= page==='classes'?'active':'' %>\" href=\"dashboard.php?page=classes\">Classes</a></li>\n                    <li class=\"nav-item\"><a class=\"nav-link <%= page==='grades'?'active':'' %>\" href=\"dashboard.php?page=grades\">Grades</a></li>\n                    <li class=\"nav-item\"><a class=\"nav-link <%= page==='attendance'?'active':'' %>\" href=\"dashboard.php?page=attendance\">Attendance</a></li>\n                    <li class=\"nav-item\"><a class=\"nav-link <%= page==='notifications'?'active':'' %>\" href=\"dashboard.php?page=notifications\">Notifications</a></li>\n                    <li class=\"nav-item\"><a class=\"nav-link <%= page==='profile'?'active':'' %>\" href=\"dashboard.php?page=profile\">Profile</a></li>\n                <% } %>\n                <% if (typeof unread !== 'undefined' && unread > 0) { %>\n                    <li class=\"nav-item\"><a class=\"nav-link\" href=\"dashboard.php?page=notifications\"><span class=\"badge bg-danger\"><%= unread %></span> New</a></li>\n                <% } %>\n                <li class=\"nav-item d-none d-lg-flex align-items-center ms-lg-2\">\n                    <span class=\"nav-user-chip\">\n                        <span class=\"user-avatar\"><%= chip_ini %></span>\n                        <span class=\"user-meta\">\n                            <strong><%= full_name %></strong>\n                            <small><%= chip_role %></small>\n                        </span>\n                    </span>\n                </li>\n                <li class=\"nav-item ms-lg-1\">\n                    <form method=\"POST\" action=\"logout.php\" class=\"d-inline\">\n                        <input type=\"hidden\" name=\"csrf_token\" value=\"<%= csrf %>\">\n                        <button type=\"submit\" class=\"btn btn-sm btn-outline-light\">Logout</button>\n                    </form>\n                </li>\n                <li class=\"nav-item ms-lg-1\">\n                    <button type=\"button\" class=\"theme-toggle-btn\" data-theme-toggle aria-label=\"Switch to dark mode\">\n                        <svg data-icon=\"light\" class=\"d-none\" width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41\"/></svg>\n                        <svg data-icon=\"dark\" width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>\n                    </button>\n                </li>\n            </ul>\n        </div>\n    </div>\n</nav>\n",
 "partials/theme_toggle_float.ejs": "<button type=\"button\" class=\"theme-toggle-float\" data-theme-toggle aria-label=\"Switch to dark mode\">\n    <svg data-icon=\"light\" class=\"d-none\" width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41\"/></svg>\n    <svg data-icon=\"dark\" width=\"17\" height=\"17\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>\n</button>\n",
 "profile.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('partials/app_head', { title: 'Profile - School Portal' }) %>\n</head>\n<body>\n<%- include('partials/navbar', { page: 'profile', unread: unread, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <div class=\"row justify-content-center\">\n        <div class=\"col-md-6\">\n            <div class=\"card shadow-sm\">\n                <div class=\"card-body text-center\">\n                    <img src=\"download.php?f=<%= encodeURIComponent(photo) %>\" class=\"profile-photo\" onerror=\"this.src='https://ui-avatars.com/api/?name=<%= encodeURIComponent(full_name) %>&background=0D1B3E&color=fff';\">\n                    <h5 class=\"fw-bold\"><%= full_name %></h5>\n                    <p class=\"text-muted small\"><%= email %> | <%= role.charAt(0).toUpperCase() + role.slice(1) %></p>\n                </div>\n            </div>\n            <div class=\"card shadow-sm mt-3\">\n                <div class=\"card-header fw-semibold card-header-soft\">Edit Profile</div>\n                <div class=\"card-body\">\n                    <form method=\"POST\" enctype=\"multipart/form-data\">\n                        <input type=\"hidden\" name=\"action\" value=\"update_profile\">\n                        <% if (role === 'teacher') { %>\n                            <div class=\"mb-2\"><label class=\"small fw-semibold\">Office Hours</label><input type=\"text\" name=\"office_hours\" class=\"form-control\" value=\"<%= data.office_hours || '' %>\"></div>\n                            <div class=\"mb-2\"><label class=\"small fw-semibold\">Contact Email</label><input type=\"email\" name=\"contact_email\" class=\"form-control\" value=\"<%= data.contact_email || '' %>\"></div>\n                        <% } else { %>\n                            <div class=\"mb-2\"><label class=\"small fw-semibold\">Phone</label><input type=\"text\" name=\"phone\" class=\"form-control\" value=\"<%= data.phone || '' %>\"></div>\n                        <% } %>\n                        <div class=\"mb-3\"><label class=\"small fw-semibold\">Profile Photo</label><input type=\"file\" name=\"photo\" class=\"form-control form-control-sm\"></div>\n                        <button type=\"submit\" class=\"btn btn-sm btn-brand\">Update Profile</button>\n                    </form>\n                </div>\n            </div>\n            <div class=\"card shadow-sm mt-3\">\n                <div class=\"card-header fw-semibold card-header-soft\">Change Password</div>\n                <div class=\"card-body\">\n                    <form method=\"POST\">\n                        <input type=\"hidden\" name=\"action\" value=\"change_password\">\n                        <div class=\"mb-2\"><label class=\"small fw-semibold\">Current Password</label><input type=\"password\" name=\"current_password\" class=\"form-control\" required></div>\n                        <div class=\"mb-2\"><label class=\"small fw-semibold\">New Password</label><input type=\"password\" name=\"new_password\" class=\"form-control\" required></div>\n                        <div class=\"mb-2\"><label class=\"small fw-semibold\">Confirm New Password</label><input type=\"password\" name=\"confirm_password\" class=\"form-control\" required></div>\n                        <button type=\"submit\" class=\"btn btn-sm btn-brand\">Change Password</button>\n                    </form>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n\n<%- include('partials/footer') %>\n</body>\n</html>\n",
 "student/attendance.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: page, unread: unread, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <h4 class=\"page-title mb-1\">My Attendance</h4>\n\n    <% if (!has_records) { %>\n    <div class=\"card\"><div class=\"empty-state\"><div class=\"empty-icon\"><%- h.icon('calendar', 26) %></div><h6>No attendance records yet</h6><p>Your teachers will record attendance per class here.</p></div></div>\n    <% } else { %>\n\n    <div class=\"row g-3 mb-3\">\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('check', 20) %></div><p class=\"stat-value <%= rate_cls %>\"><%= rate %>%</p><span class=\"stat-label\">Attendance Rate</span></div></div>\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('check', 20) %></div><p class=\"stat-value\"><%= counts.present %></p><span class=\"stat-label\">Present</span></div></div>\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('calendar', 20) %></div><p class=\"stat-value\"><%= counts.late %></p><span class=\"stat-label\">Late</span></div></div>\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('inbox', 20) %></div><p class=\"stat-value\"><%= counts.absent + counts.excused %></p><span class=\"stat-label\">Absent / Excused</span></div></div>\n    </div>\n\n    <div class=\"card shadow-sm\"><div class=\"table-responsive\"><table class=\"table table-hover table-sm align-middle mb-0\">\n    <thead><tr><th>Date</th><th>Subject</th><th>Section</th><th>Status</th></tr></thead><tbody>\n    <% records.forEach((r) => { %>\n        <tr><td><%= r.date %></td><td><%= r.subject %></td><td><%= r.section %></td>\n        <td><span class=\"badge bg-<%= r.color %>\"><%= r.status_uc %></span></td></tr>\n    <% }) %>\n    </tbody></table></div></div>\n\n    <% } %>\n\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n",
 "student/class.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: page, unread: unread, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <% if (error) { %>\n    <div class=\"alert alert-danger\"><%= error %></div>\n    <% } else { %>\n\n    <div class=\"page-header\">\n        <div>\n            <a class=\"small d-inline-block mb-1\" href=\"dashboard.php?page=classes\">&larr; My Classes</a>\n            <h4 class=\"page-title\"><%= c.subject %></h4>\n            <p class=\"page-subtitle\"><%= c.section %> &middot; SY <%= c.school_year %></p>\n        </div>\n    </div>\n\n    <ul class=\"nav nav-tabs mb-3\">\n        <li class=\"nav-item\"><a class=\"nav-link <%= tab === 'stream' ? 'active' : '' %>\" href=\"dashboard.php?page=class&id=<%= class_id %>&tab=stream\">Stream</a></li>\n        <li class=\"nav-item\"><a class=\"nav-link <%= tab === 'assignments' ? 'active' : '' %>\" href=\"dashboard.php?page=class&id=<%= class_id %>&tab=assignments\">Assignments</a></li>\n    </ul>\n\n    <% if (tab === 'stream') { %>\n        <h5 class=\"fw-bold mb-2\">Announcements</h5>\n        <% if (anns.length) { %><div class=\"list-group mt-2\"><% anns.forEach((a) => { %>\n        <div class=\"list-group-item\"><div class=\"fw-semibold\"><%= a.title %></div>\n        <small><%- a.content_html %></small>\n        <% if (a.attachment) { %><br><a href=\"download.php?f=<%= a.attachment_href %>\" target=\"_blank\" class=\"small\">Attachment</a><% } %>\n        <br><small class=\"text-muted\"><%= a.posted_at %></small></div>\n        <% }) %></div><% } else { %>\n        <div class=\"alert alert-info mt-2\">No announcements yet.</div>\n        <% } %>\n\n        <!-- Grade summary: published terms only -->\n        <div class=\"card shadow-sm mt-4\"><div class=\"card-header fw-semibold card-header-soft\">My Grades Summary</div><div class=\"card-body\">\n        <% if (grades_summary.length) { %>\n            <% grades_summary.forEach((tt) => { %>\n            <div class=\"mb-3\"><div class=\"d-flex justify-content-between align-items-center\"><strong><%= tt.label %></strong>\n            <% if (tt.grade !== null) { %>\n                <span class=\"d-flex align-items-center gap-2\"><span class=\"rc-grade <%= h.rc_grade_class(tt.grade, true) %>\"><%- h.rc_grade(tt.grade, true) %></span><span class=\"badge bg-primary\"><%- h.rc_label(tt.descriptor, true) %></span><%- h.rc_result(tt.passed, true) %></span>\n            <% } else { %>\n                <span class=\"text-muted small\">No grade yet</span>\n            <% } %>\n            </div></div>\n            <% }) %>\n        <% } else { %>\n            <p class=\"text-muted small mb-0\">No grades published yet. Your teacher will publish term grades here.</p>\n        <% } %>\n        </div></div>\n\n        <!-- Attendance summary -->\n        <div class=\"card shadow-sm mt-3\"><div class=\"card-header fw-semibold card-header-soft\">My Attendance</div><div class=\"card-body\">\n        <% if (att_summary.length) { %>\n            <% att_summary.forEach((a) => { %>\n            <div class=\"d-flex justify-content-between\"><span class=\"text-<%= a.color %> fw-semibold\"><%= a.status_uc %></span><span><%= a.cnt %> (<%= a.pct %>%)</span></div>\n            <% }) %>\n        <% } else { %>\n            <p class=\"text-muted small mb-0\">No attendance records yet.</p>\n        <% } %>\n        </div></div>\n\n    <% } else if (tab === 'assignments') { %>\n        <h5 class=\"fw-bold\">Assignments</h5>\n        <% if (!assigns.length) { %>\n        <div class=\"alert alert-info mt-2\">No assignments yet.</div>\n        <% } else { %>\n        <div class=\"list-group mt-2\">\n        <% assigns.forEach((a) => { %>\n            <div class=\"list-group-item\">\n                <div class=\"d-flex justify-content-between align-items-start\">\n                    <div>\n                        <div class=\"fw-semibold\"><%= a.title %></div>\n                        <small class=\"text-muted\">Due: <%= a.due_date %></small>\n                        <% if (a.attachment) { %> | <a href=\"download.php?f=<%= a.attachment_href %>\" target=\"_blank\" class=\"small\">Attachment</a><% } %>\n                        <% if (a.description_html) { %><br><small><%- a.description_html %></small><% } %>\n                        <br><small class=\"text-muted\">\n                            <% if (a.requires_file) { %>File required &middot; Accepted: <%= a.exts_csv %> &middot; Max <%= a.max_size_mb %> MB<% } else { %>File optional<% } %>\n                            &middot; <%= a.late_label %>\n                        </small>\n                        <br><small class=\"text-muted\"><i class=\"bi bi-shield-lock\"></i> Your submission is visible only to you and your teacher.</small>\n                        <% if (a.existing) { %><br><small class=\"text-muted\">Submitted: <%= a.submitted_at %></small><% } %>\n                        <% if (a.existing && a.feedback) { %><br><small class=\"text-muted\">Feedback: <%= a.feedback %></small><% } %>\n                    </div>\n                    <div class=\"text-end\">\n                        <span class=\"badge bg-<%= a.status_color %>\"><%= a.status %></span>\n                        <% if (a.can_submit) { %>\n                            <button class=\"btn btn-sm btn-outline-primary mt-1\" data-bs-toggle=\"modal\" data-bs-target=\"#subModal<%= a.id %>\"><%= a.button %></button>\n                        <% } %>\n                    </div>\n                </div>\n            </div>\n            <div class=\"modal fade\" id=\"subModal<%= a.id %>\">\n                <div class=\"modal-dialog\">\n                    <form method=\"POST\" enctype=\"multipart/form-data\" class=\"modal-content\">\n                        <input type=\"hidden\" name=\"action\" value=\"submit_assignment\">\n                        <input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\">\n                        <input type=\"hidden\" name=\"assignment_id\" value=\"<%= a.id %>\">\n                        <div class=\"modal-header\"><h5 class=\"modal-title\">Submit: <%= a.title %></h5><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\"></button></div>\n                        <div class=\"modal-body\">\n                            <% if (a.requires_file) { %>\n                                <p class=\"small text-muted mb-2\">Accepted types: <strong><%= a.exts_csv %></strong> &middot; Max size: <strong><%= a.max_size_mb %> MB</strong> &middot; Due: <strong><%= a.due_date %></strong></p>\n                                <input type=\"file\" name=\"file\" class=\"form-control\" required accept=\"<%= a.accept_attr %>\">\n                            <% } else { %>\n                                <input type=\"file\" name=\"file\" class=\"form-control\">\n                            <% } %>\n                            <small class=\"text-muted d-block mt-2\"><i class=\"bi bi-shield-lock\"></i> Your file is visible only to you and your teacher.</small>\n                        </div>\n                        <div class=\"modal-footer\"><button type=\"submit\" class=\"btn btn-sm btn-brand\">Submit</button></div>\n                    </form>\n                </div>\n            </div>\n        <% }) %>\n        </div>\n        <% } %>\n    <% } %>\n\n    <% } %>\n\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n",
 "student/classes.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: page, unread: unread, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <div class=\"d-flex justify-content-between align-items-center mb-3\">\n        <h4 class=\"page-title\">My Classes</h4>\n        <button class=\"btn btn-sm btn-accent\" data-bs-toggle=\"modal\" data-bs-target=\"#joinModal\">+ Join Class</button>\n    </div>\n\n    <% if (list.length) { %>\n    <div class=\"row g-3\">\n        <% list.forEach((c) => { %>\n        <div class=\"col-md-4 col-sm-6\"><div class=\"card class-card shadow-sm accent-<%= c.accent %>\"><div class=\"card-body\">\n            <h5 class=\"card-title fw-bold mb-1\"><%= c.subject %></h5>\n            <small class=\"text-muted d-block\"><%= c.section %> &middot; SY <%= c.school_year %></small>\n            <small class=\"stu-teacher d-block mb-2\"><%= c.teacher !== '' ? c.teacher : 'Teacher TBA' %></small>\n            <div class=\"d-flex justify-content-between align-items-center\">\n                <% if (c.latest !== null) { %>\n                <span class=\"stu-grade-line\"><span class=\"rc-grade <%= h.rc_grade_class(c.latest, true) %>\"><%- h.rc_grade(c.latest, true) %></span><small class=\"rc-desc\"><%- h.rc_label(c.latest_desc, true) %></small></span>\n                <% } else { %>\n                <small class=\"text-muted\">No grades yet</small>\n                <% } %>\n                <a href=\"dashboard.php?page=class&id=<%= c.id %>\" class=\"btn btn-sm btn-brand\">Open</a>\n            </div>\n        </div></div></div>\n        <% }) %>\n    </div>\n    <% } else { %>\n    <div class=\"card\"><div class=\"empty-state\"><div class=\"empty-icon\"><%- h.icon('users', 26) %></div><h6>No classes yet</h6><p>Enter the join code your teacher gave you to enroll.</p><button class=\"btn btn-accent\" data-bs-toggle=\"modal\" data-bs-target=\"#joinModal\">+ Join Class</button></div></div>\n    <% } %>\n\n    <div class=\"modal fade\" id=\"joinModal\">\n        <div class=\"modal-dialog\">\n            <form method=\"POST\" class=\"modal-content\">\n                <input type=\"hidden\" name=\"action\" value=\"join_class\">\n                <div class=\"modal-header\"><h5 class=\"modal-title\">Join a Class</h5><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\"></button></div>\n                <div class=\"modal-body\">\n                    <p class=\"small text-muted\">Enter the class join code provided by your teacher.</p>\n                    <input type=\"text\" name=\"join_code\" class=\"form-control\" placeholder=\"Enter code\" required style=\"text-transform:uppercase;\">\n                </div>\n                <div class=\"modal-footer\"><button type=\"submit\" class=\"btn btn-sm btn-brand\">Join</button></div>\n            </form>\n        </div>\n    </div>\n\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n",
 "student/dashboard.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: page, unread: unread, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <div class=\"page-header\">\n        <div>\n            <h4 class=\"page-title\">Hi, <%= first %>!</h4>\n            <p class=\"page-subtitle\">Here's how you're doing<% if (sy !== '') { %> for SY <%= sy %><% } %>.</p>\n        </div>\n        <div class=\"d-flex gap-2\">\n            <a href=\"dashboard.php?page=grades\" class=\"btn btn-sm btn-accent\">View Report Card</a>\n            <a href=\"dashboard.php?page=attendance\" class=\"btn btn-sm btn-outline-secondary\">My Attendance</a>\n        </div>\n    </div>\n\n    <div class=\"row g-3 mb-3\">\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('school', 20) %></div><p class=\"stat-value\"><%= enrolled_count %></p><span class=\"stat-label\">Enrolled Classes</span></div></div>\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('clipboard', 20) %></div><p class=\"stat-value\"><%= upcoming_count %></p><span class=\"stat-label\">Upcoming Tasks</span></div></div>\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('calendar', 20) %></div><p class=\"stat-value <%= att.cls %>\"><%= att.value %></p><span class=\"stat-label\">Attendance Rate</span></div></div>\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('award', 20) %></div><p class=\"stat-value <%= overall.cls %>\"><%= overall.value %></p><span class=\"stat-label\">Overall Average<%- overall.desc %></span></div></div>\n    </div>\n\n    <% if (need_attention_parts.length) { %>\n    <div class=\"alert alert-warning d-flex align-items-start gap-2\"><%- h.icon('bell', 18) %><div><strong>Needs attention:</strong> <%- need_attention_parts.join(' &middot; ') %></div></div>\n    <% } %>\n\n    <% if (enrolled.length) { %>\n    <h5 class=\"fw-bold mt-4 mb-3\">My Classes</h5><div class=\"row g-3\">\n        <% enrolled.forEach((c) => { %>\n        <div class=\"col-md-4 col-sm-6\"><div class=\"card class-card shadow-sm accent-<%= c.accent %>\"><div class=\"card-body\">\n            <h6 class=\"card-title mb-1\"><%= c.subject %></h6>\n            <small class=\"text-muted d-block\"><%= c.section %></small>\n            <small class=\"stu-teacher d-block mb-2\"><%= c.teacher !== '' ? c.teacher : 'Teacher TBA' %> &middot; <%= c.released %> of <%= c.terms %> terms released</small>\n            <div class=\"d-flex justify-content-between align-items-center\">\n                <% if (c.latest !== null) { %>\n                <span class=\"stu-grade-line\"><span class=\"rc-grade <%= h.rc_grade_class(c.latest, true) %>\"><%- h.rc_grade(c.latest, true) %></span><small class=\"rc-desc\"><%- h.rc_label(c.latest_desc, true) %></small></span>\n                <% } else { %>\n                <small class=\"text-muted\">No grades yet</small>\n                <% } %>\n                <a href=\"dashboard.php?page=class&id=<%= c.id %>\" class=\"btn btn-sm btn-brand\">Open</a>\n            </div>\n        </div></div></div>\n        <% }) %>\n    </div>\n    <% } else { %>\n    <div class=\"card\"><div class=\"empty-state\"><div class=\"empty-icon\"><%- h.icon('school', 26) %></div><h6>No classes yet</h6><p>Join a class with the code from your teacher to see your grades here.</p><a href=\"dashboard.php?page=classes\" class=\"btn btn-accent\">+ Join Class</a></div></div>\n    <% } %>\n\n    <% if (upcoming.length) { %>\n    <h5 class=\"fw-bold mt-4 mb-3\">Upcoming Assignments</h5><div class=\"list-group\">\n        <% upcoming.forEach((a) => { %>\n        <div class=\"list-group-item d-flex justify-content-between align-items-center\">\n            <div><div class=\"fw-semibold\"><%= a.title %></div>\n            <small class=\"text-muted\"><%= a.subject %></small></div>\n            <span class=\"stu-due-chip<%= a.soon ? ' ' + a.soon : '' %>\"><%= a.chip %></span></div>\n        <% }) %>\n    </div>\n    <% } %>\n\n    <% if (latest_ann) { %>\n    <div class=\"card shadow-sm mt-3 border-warning\"><div class=\"card-body\"><small class=\"text-warning fw-bold\">LATEST ANNOUNCEMENT</small>\n    <h6 class=\"fw-bold mb-1\"><%= latest_ann.title %></h6>\n    <small><%- latest_ann.content_html %></small>\n    <br><small class=\"text-muted\"><%= latest_ann.subject %> - <%= latest_ann.posted_at %></small></div></div>\n    <% } %>\n\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n",
 "student/grades.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: page, unread: unread, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <% if (info) { %>\n    <div class=\"alert alert-info\"><%= info %></div>\n    <% } else { %>\n\n    <div class=\"page-header\">\n        <div>\n            <h4 class=\"page-title\">Report Card</h4>\n            <p class=\"page-subtitle\">Released Term Grades and your general average.</p>\n        </div>\n        <div class=\"d-flex gap-2\">\n            <button type=\"button\" class=\"btn btn-sm btn-outline-secondary\" onclick=\"window.print()\">Print</button>\n        </div>\n    </div>\n\n    <div class=\"stu-learner d-flex flex-wrap justify-content-between align-items-end gap-2 mb-2\">\n        <div>\n            <strong><%= me.full_name %></strong>\n            <small class=\"text-muted d-block\">\n                <%= me.student_number %><%= me.section ? ' &middot; ' + me.section : '' %>\n            </small>\n        </div>\n        <small class=\"text-muted\">SY <%= year_label %> &middot; DO 015 reporting scale</small>\n    </div>\n\n    <% if (years.length > 1) { %>\n    <div class=\"rc-year-tabs\">\n        <% years.forEach((y) => { %>\n        <a class=\"rc-year-tab<%= y.active ? ' is-active' : '' %>\" href=\"dashboard.php?page=grades&amp;year=<%= y.yid %>\"><%= y.label %></a>\n        <% }) %>\n    </div>\n    <% } %>\n\n    <div class=\"card rc-card\">\n        <div class=\"table-responsive\">\n            <table class=\"table rc-table mb-0\">\n                <thead>\n                    <tr>\n                        <th class=\"rc-th-subject\">Subject</th>\n                        <% terms.forEach((t) => { %>\n                        <th class=\"rc-th-term\"><%= t.label %></th>\n                        <% }) %>\n                        <th class=\"rc-th-final\">Final<br><small>General Avg</small></th>\n                    </tr>\n                </thead>\n                <tbody>\n                <% subjects.forEach((s) => { %>\n                    <tr class=\"rc-subject-row<%= s.any ? '' : ' is-empty' %>\">\n                        <th class=\"rc-td-subject\" scope=\"row\">\n                            <%= s.subject %>\n                            <small><%= s.section %><%= s.shown_cluster !== '' ? ' &middot; ' + s.shown_cluster : '' %></small>\n                        </th>\n                        <% s.cells.forEach((f) => { %>\n                        <td class=\"rc-td-term\">\n                            <% if (!f.shown) { %>\n                                <span class=\"rc-hidden\" title=\"Not released yet\">&mdash;</span>\n                            <% } else { %>\n                                <span class=\"rc-grade <%= h.rc_grade_class(f.grade, true) %>\"><%- h.rc_grade(f.grade, true) %></span>\n                                <small class=\"rc-desc\"><%- h.rc_label(f.desc, true) %></small>\n                            <% } %>\n                        </td>\n                        <% }) %>\n                        <td class=\"rc-td-final\">\n                            <span class=\"rc-grade rc-grade-final <%= h.rc_grade_class(s.sub_final, s.sub_final !== null) %>\"><%- h.rc_grade(s.sub_final, s.sub_final !== null) %></span>\n                            <%- h.rc_result(s.passed, s.sub_final !== null) %>\n                        </td>\n                    </tr>\n                <% }) %>\n\n                <tr class=\"rc-general-row\">\n                    <th class=\"rc-td-subject\" scope=\"row\">General Average</th>\n                    <td class=\"rc-td-general\" colspan=\"<%= terms.length %>\">\n                        <% if (!general) { %>\n                            <span class=\"text-muted\">No released grades yet.</span>\n                        <% } else { %>\n                            <span class=\"rc-grade <%= h.rc_grade_class(general.value, true) %>\"><%- h.rc_grade(general.value, true) %></span>\n                            <small class=\"rc-desc\"><%- h.rc_label(general.desc, true) %></small>\n                            <%- h.rc_result(general.passed, true) %>\n                        <% } %>\n                    </td>\n                    <td class=\"rc-td-final\">\n                        <% if (!general) { %><span class=\"rc-grade rc-g-none\">&mdash;</span><% } else { %>\n                            <span class=\"rc-grade rc-grade-final <%= h.rc_grade_class(general.value, true) %>\"><%- h.rc_grade(general.value, true) %></span>\n                        <% } %>\n                    </td>\n                </tr>\n                </tbody>\n            </table>\n        </div>\n    </div>\n\n    <div class=\"rc-legend\">\n        <span class=\"rc-legend-title\">DO 015 scale</span>\n        <% legend.forEach((b) => { %>\n        <span class=\"rc-legend-item\"><i class=\"rc-swatch <%= b.cls %>\"></i><%= b.label %></span>\n        <% }) %>\n        <span class=\"rc-legend-item\"><i class=\"rc-swatch rc-g-none\"></i>Not graded</span>\n        <span class=\"rc-legend-note\">Passing mark: <%= passing_mark %></span>\n    </div>\n\n    <% } %>\n\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n",
 "student/notifications.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: title }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: page, unread: unread, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <h4 class=\"page-title mb-1\">Notifications</h4>\n\n    <% if (!list.length) { %>\n    <div class=\"alert alert-info\">No notifications.</div>\n    <% } else { %>\n    <div class=\"list-group\">\n    <% list.forEach((n) => { %>\n        <div class=\"list-group-item\"><a href=\"<%= n.link %>\" class=\"text-decoration-none\"><%= n.message %></a>\n        <br><small class=\"text-muted\"><%= n.created_at %></small></div>\n    <% }) %>\n    </div>\n    <% } %>\n\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n",
 "teacher/attendance.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: 'School Portal' }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: 'attendance', unread: 0, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <% if (!cls) { %>\n        <div class=\"alert alert-danger\">Class not found.</div>\n    <% } else { %>\n    <div class=\"page-header\">\n        <div>\n            <a class=\"small d-inline-block mb-1\" href=\"dashboard.php?page=class&id=<%= class_id %>\">&larr; Back to Class</a>\n            <h4 class=\"page-title\">Attendance: <%= cls.subject %></h4>\n            <p class=\"page-subtitle\"><%= cls.section %></p>\n        </div>\n        <form method=\"GET\" class=\"row g-2 align-items-end\">\n            <div class=\"col-auto\">\n                <input type=\"hidden\" name=\"page\" value=\"attendance\">\n                <input type=\"hidden\" name=\"id\" value=\"<%= class_id %>\">\n                <label class=\"form-label small mb-0\">Date</label>\n                <input type=\"date\" name=\"date\" class=\"form-control form-control-sm\" value=\"<%= date %>\">\n            </div>\n            <div class=\"col-auto\"><button type=\"submit\" class=\"btn btn-sm btn-outline-primary\">View</button></div>\n        </form>\n    </div>\n\n    <form method=\"POST\">\n        <input type=\"hidden\" name=\"action\" value=\"mark_attendance\">\n        <input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\">\n        <input type=\"hidden\" name=\"date\" value=\"<%= date %>\">\n        <div class=\"table-responsive\">\n        <table class=\"table table-hover table-sm\">\n            <thead><tr><th>Student</th><th>Status</th></tr></thead>\n            <tbody>\n            <% students.forEach((s) => {\n                const sid = Number(s.id);\n                const current = att_map[sid] ?? 'present';\n            %>\n                <tr>\n                    <td><%= s.full_name %></td>\n                    <td>\n                        <input type=\"hidden\" name=\"student_id[]\" value=\"<%= sid %>\">\n                        <div class=\"form-check form-check-inline\">\n                            <input class=\"form-check-input\" type=\"radio\" name=\"status_<%= sid %>\" value=\"present\" id=\"p_<%= sid %>\" <%= current==='present'?'checked':'' %>>\n                            <label class=\"form-check-label small\" for=\"p_<%= sid %>\">Present</label>\n                        </div>\n                        <div class=\"form-check form-check-inline\">\n                            <input class=\"form-check-input\" type=\"radio\" name=\"status_<%= sid %>\" value=\"late\" id=\"l_<%= sid %>\" <%= current==='late'?'checked':'' %>>\n                            <label class=\"form-check-label small\" for=\"l_<%= sid %>\">Late</label>\n                        </div>\n                        <div class=\"form-check form-check-inline\">\n                            <input class=\"form-check-input\" type=\"radio\" name=\"status_<%= sid %>\" value=\"excused\" id=\"e_<%= sid %>\" <%= current==='excused'?'checked':'' %>>\n                            <label class=\"form-check-label small\" for=\"e_<%= sid %>\">Excused</label>\n                        </div>\n                        <div class=\"form-check form-check-inline\">\n                            <input class=\"form-check-input\" type=\"radio\" name=\"status_<%= sid %>\" value=\"absent\" id=\"a_<%= sid %>\" <%= current==='absent'?'checked':'' %>>\n                            <label class=\"form-check-label small\" for=\"a_<%= sid %>\">Absent</label>\n                        </div>\n                    </td>\n                </tr>\n            <% }); %>\n            </tbody>\n        </table>\n        </div>\n        <button type=\"submit\" class=\"btn btn-brand\">Save Attendance</button>\n    </form>\n    <% } %>\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n",
 "teacher/class.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: 'School Portal' }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: 'class', unread: 0, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <% if (!cls) { %>\n        <div class=\"alert alert-danger\">Class not found.</div>\n    <% } else { %>\n    <div class=\"page-header\">\n        <div>\n            <a class=\"small d-inline-block mb-1\" href=\"dashboard.php\">&larr; My Classes</a>\n            <h4 class=\"page-title\"><%= cls.subject %></h4>\n            <p class=\"page-subtitle\"><%= cls.section %> &middot; SY <%= cls.school_year %></p>\n        </div>\n        <div class=\"d-flex gap-2 flex-wrap\">\n            <a href=\"dashboard.php?page=grades&id=<%= class_id %>\" class=\"btn btn-sm btn-outline-primary\">Grades</a>\n            <a href=\"dashboard.php?page=attendance&id=<%= class_id %>\" class=\"btn btn-sm btn-outline-primary\">Attendance</a>\n            <a href=\"dashboard.php?page=settings&id=<%= class_id %>\" class=\"btn btn-sm btn-outline-secondary\">Settings</a>\n        </div>\n    </div>\n\n    <ul class=\"nav nav-tabs mb-3\" id=\"classTabs\">\n        <li class=\"nav-item\"><a class=\"nav-link <%= tab==='stream'?'active':'' %>\" href=\"dashboard.php?page=class&id=<%= class_id %>&tab=stream\">Stream</a></li>\n        <li class=\"nav-item\"><a class=\"nav-link <%= tab==='assignments'?'active':'' %>\" href=\"dashboard.php?page=class&id=<%= class_id %>&tab=assignments\">Assignments</a></li>\n        <li class=\"nav-item\"><a class=\"nav-link <%= tab==='students'?'active':'' %>\" href=\"dashboard.php?page=class&id=<%= class_id %>&tab=students\">Students</a></li>\n    </ul>\n\n    <% if (tab === 'stream') { %>\n        <div class=\"mb-4\">\n        <div class=\"d-flex justify-content-between align-items-center mb-2\"><h5 class=\"fw-bold mb-0\">Announcements</h5>\n        <button class=\"btn btn-sm btn-accent\" data-bs-toggle=\"modal\" data-bs-target=\"#annModal\">+ Post</button></div>\n        <% let first = true; %>\n        <% (anns || []).forEach((a) => { %>\n            <% if (first) { %><div class=\"list-group mt-2\"><% first = false; } %>\n            <div class=\"list-group-item\"><div class=\"fw-semibold\"><%= a.title %></div>\n            <small><%- a.content_html %></small>\n            <% if (a.attachment) { %><br><a href=\"download.php?f=<%= encodeURIComponent(a.attachment) %>\" target=\"_blank\" class=\"small\">View Attachment</a><% } %>\n            <br><small class=\"text-muted\"><%- a.posted_at %></small></div>\n        <% }); %>\n        <% if (!first) { %></div><% } %>\n        <div class=\"modal fade\" id=\"annModal\">\n            <div class=\"modal-dialog\">\n                <form method=\"POST\" enctype=\"multipart/form-data\" class=\"modal-content\">\n                    <input type=\"hidden\" name=\"action\" value=\"create_announcement\">\n                    <input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\">\n                    <div class=\"modal-header\"><h5 class=\"modal-title\">Post Announcement</h5><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\"></button></div>\n                    <div class=\"modal-body\">\n                        <div class=\"mb-2\"><input type=\"text\" name=\"title\" class=\"form-control\" placeholder=\"Title\" required></div>\n                        <div class=\"mb-2\"><textarea name=\"content\" class=\"form-control\" rows=\"3\" placeholder=\"Content\" required></textarea></div>\n                        <div><input type=\"file\" name=\"attachment\" class=\"form-control form-control-sm\"></div>\n                    </div>\n                    <div class=\"modal-footer\"><button type=\"submit\" class=\"btn btn-sm btn-brand\">Post</button></div>\n                </form>\n            </div>\n        </div>\n    <% } else if (tab === 'assignments') { %>\n        <div class=\"d-flex justify-content-between align-items-center mb-2\">\n            <h5 class=\"fw-bold mb-0\">Assignments</h5>\n            <button class=\"btn btn-sm btn-accent\" data-bs-toggle=\"modal\" data-bs-target=\"#assignModal\">+ Create</button>\n        </div>\n        <% if (!assignments.length) { %>\n            <div class=\"alert alert-info mt-2\">No assignments yet.</div>\n        <% } else { %>\n            <div class=\"list-group mt-2\">\n            <% assignments.forEach((a) => { %>\n                <div class=\"list-group-item\"><div class=\"d-flex justify-content-between\">\n                <div><div class=\"fw-semibold\"><%= a.title %>\n                <% if (Number(a.requires_file || 0) !== 0) { %> <span class=\"badge bg-primary ms-1\">file required</span><% } %>\n                <% if (Number(a.allow_late || 0) === 0) { %> <span class=\"badge bg-warning text-dark ms-1\">late closed</span><% } %>\n                </div><small class=\"text-muted\">Due: <%- a.due_date %></small></div>\n                <div><span class=\"badge bg-info\"><%= a.sub_count %> submissions</span>\n                <% if (a.late_count) { %> <span class=\"badge bg-warning text-dark\"><%= a.late_count %> late</span><% } %>\n                <a href=\"dashboard.php?page=submissions&id=<%= Number(a.id) %>\" class=\"btn btn-sm btn-outline-primary ms-2\">View</a></div>\n                </div></div>\n            <% }); %>\n            </div>\n        <% } %>\n        <div class=\"modal fade\" id=\"assignModal\">\n            <div class=\"modal-dialog\">\n                <form method=\"POST\" enctype=\"multipart/form-data\" class=\"modal-content\">\n                    <input type=\"hidden\" name=\"action\" value=\"create_assignment\">\n                    <input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\">\n                    <div class=\"modal-header\"><h5 class=\"modal-title\">Create Assignment</h5><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\"></button></div>\n                    <div class=\"modal-body\">\n                        <div class=\"mb-2\"><input type=\"text\" name=\"title\" class=\"form-control\" placeholder=\"Title\" required></div>\n                        <div class=\"mb-2\"><textarea name=\"description\" class=\"form-control\" rows=\"3\" placeholder=\"Description\"></textarea></div>\n                        <div class=\"mb-2\"><label class=\"small fw-semibold\">Due Date</label><input type=\"date\" name=\"due_date\" class=\"form-control\" required></div>\n                        <div class=\"mb-2\"><input type=\"file\" name=\"attachment\" class=\"form-control form-control-sm\" aria-label=\"Attachment (optional)\"></div>\n                        <hr>\n                        <div class=\"mb-2\"><label class=\"small fw-semibold d-block\">Submission</label>\n                            <div class=\"form-check form-check-inline\"><input class=\"form-check-input\" type=\"checkbox\" name=\"requires_file\" id=\"reqFile\" checked><label class=\"form-check-label small\" for=\"reqFile\">Students must upload a file</label></div>\n                            <div class=\"form-check form-check-inline\"><input class=\"form-check-input\" type=\"checkbox\" name=\"allow_late\" id=\"allowLate\" checked><label class=\"form-check-label small\" for=\"allowLate\">Allow late (marked Late)</label></div>\n                        </div>\n                        <div class=\"row g-2 mb-2\">\n                            <div class=\"col-7\"><label class=\"small fw-semibold\">Allowed types (blank = default)</label><input type=\"text\" name=\"allowed_exts\" class=\"form-control form-control-sm\" placeholder=\"pdf, docx, txt, jpg, zip\"></div>\n                            <div class=\"col-5\"><label class=\"small fw-semibold\">Max size (MB)</label><input type=\"number\" name=\"max_size_mb\" class=\"form-control form-control-sm\" value=\"10\" min=\"0.5\" max=\"25\" step=\"0.5\"></div>\n                        </div>\n                        <div class=\"mb-1\"><label class=\"small fw-semibold\">Cutoff date (optional, only if late disabled)</label><input type=\"date\" name=\"cutoff_date\" class=\"form-control form-control-sm\"></div>\n                    </div>\n                    <div class=\"modal-footer\"><button type=\"submit\" class=\"btn btn-sm btn-brand\">Create</button></div>\n                </form>\n            </div>\n        </div>\n    <% } else if (tab === 'students') { %>\n        <div class=\"d-flex justify-content-between align-items-center mb-2\">\n            <h5 class=\"fw-bold mb-0\">Students (<%= students_list.length %>)</h5>\n            <form method=\"GET\" class=\"d-flex gap-1 align-items-center\">\n                <input type=\"hidden\" name=\"page\" value=\"class\">\n                <input type=\"hidden\" name=\"id\" value=\"<%= class_id %>\">\n                <input type=\"hidden\" name=\"tab\" value=\"students\">\n                <input type=\"text\" name=\"search\" class=\"form-control form-control-sm\" style=\"width:180px;\" placeholder=\"Search name...\" value=\"<%= search %>\">\n                <button type=\"submit\" class=\"btn btn-sm btn-outline-primary\">Search</button>\n            </form>\n        </div>\n        <% if (!students_list.length) { %>\n            <div class=\"alert alert-info mt-2\">No students enrolled.</div>\n        <% } else { %>\n            <div class=\"table-responsive mt-2\">\n                <table class=\"table table-hover\">\n                    <thead><tr><th>Name</th><th>ID</th><th>Section</th><th></th></tr></thead>\n                    <tbody>\n                    <% students_list.forEach((s) => { %>\n                        <tr>\n                            <td><%= s.full_name %></td>\n                            <td><%= s.student_number %></td>\n                            <td><%= s.section ?? '' %></td>\n                            <td>\n                                <form method=\"POST\" onsubmit=\"return confirm('Remove this student?')\">\n                                    <input type=\"hidden\" name=\"action\" value=\"remove_student\">\n                                    <input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\">\n                                    <input type=\"hidden\" name=\"student_id\" value=\"<%= Number(s.id) %>\">\n                                    <button type=\"submit\" class=\"btn btn-sm btn-outline-danger\">Remove</button>\n                                </form>\n                            </td>\n                        </tr>\n                    <% }); %>\n                    </tbody>\n                </table>\n            </div>\n        <% } %>\n    <% } %>\n    <% } %>\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n",
 "teacher/create_class.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: 'School Portal' }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: 'create_class', unread: 0, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <div class=\"row justify-content-center\">\n        <div class=\"col-md-8\">\n            <div class=\"card shadow-sm\">\n                <div class=\"card-body p-4\">\n                    <h4 class=\"page-title mb-1\">Create New Class</h4>\n                    <form method=\"POST\">\n                        <input type=\"hidden\" name=\"action\" value=\"create_class\">\n                        <div class=\"row g-3\">\n                            <div class=\"col-md-6\">\n                                <label class=\"form-label fw-semibold small\">Subject</label>\n                                <input type=\"text\" name=\"subject\" class=\"form-control\" required>\n                            </div>\n                            <div class=\"col-md-6\">\n                                <label class=\"form-label fw-semibold small\">Section</label>\n                                <input type=\"text\" name=\"section\" class=\"form-control\" required>\n                            </div>\n                            <div class=\"col-md-6\">\n                                <label class=\"form-label fw-semibold small\">School Year</label>\n                                <input type=\"text\" name=\"school_year\" class=\"form-control\" placeholder=\"e.g. 2026-2027\" required>\n                            </div>\n                            <div class=\"col-md-6\">\n                                <label class=\"form-label fw-semibold small\">Academic Year (terms)</label>\n                                <select name=\"academic_year_id\" class=\"form-select\">\n                                    <% years.forEach((y) => { %>\n                                        <option value=\"<%= Number(y.id) %>\" <%= Number(y.is_active || 0) !== 0 ? 'selected' : '' %>><%= y.label %><%= Number(y.is_active || 0) !== 0 ? ' (current)' : '' %></option>\n                                    <% }); %>\n                                    <% if (!years.length) { %><option value=\"\">No academic years set up</option><% } %>\n                                </select>\n                            </div>\n                            <div class=\"col-12\">\n                                <label class=\"form-label fw-semibold small\">Description (optional)</label>\n                                <textarea name=\"description\" class=\"form-control\" rows=\"1\"></textarea>\n                            </div>\n                        </div>\n                        <div class=\"mt-3\">\n                            <button type=\"submit\" class=\"btn btn-brand\">Create Class</button>\n                            <a href=\"dashboard.php\" class=\"btn btn-outline-secondary\">Cancel</a>\n                        </div>\n                    </form>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n",
 "teacher/dashboard.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: 'School Portal' }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: 'dashboard', unread: 0, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <div class=\"page-header\">\n        <div>\n            <h4 class=\"page-title\">My Classes</h4>\n            <p class=\"page-subtitle\">Manage your classes, grades, and attendance</p>\n        </div>\n        <a href=\"dashboard.php?page=create_class\" class=\"btn btn-sm btn-accent\">+ New Class</a>\n    </div>\n\n    <div class=\"row g-3 mb-3\">\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('book', 20) %></div><p class=\"stat-value\"><%= classes.length %></p><span class=\"stat-label\">Active Classes</span></div></div>\n        <div class=\"col-md-3 col-6\"><div class=\"card stat-card\"><div class=\"stat-icon\"><%- h.icon('users', 20) %></div><p class=\"stat-value\"><%= total_students %></p><span class=\"stat-label\">Total Students</span></div></div>\n    </div>\n\n    <% if (classes.length) { %>\n        <div class=\"row g-3\">\n        <% classes.forEach((c) => { %>\n            <div class=\"col-md-4 col-sm-6\">\n            <div class=\"card class-card shadow-sm accent-<%= c.accent %>\">\n            <div class=\"card-body\">\n            <h5 class=\"card-title mb-1\"><%= c.subject %></h5>\n            <p class=\"card-text small text-muted mb-1\"><%= c.section %> &middot; <%= c.school_year %></p>\n            <p class=\"card-text small text-muted mb-3\"><%= c.student_count %> students &middot; <%- c.state %></p>\n            <% if (c.prog && c.prog.total > 0) { %>\n                <div class=\"gb-progress mb-3\" role=\"progressbar\" aria-valuenow=\"<%= c.pct %>\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-label=\"Grading progress\">\n                <div class=\"gb-progress-fill\" style=\"width:<%= c.pct %>%\"></div></div>\n            <% } %>\n            <div class=\"d-flex gap-2 flex-wrap\">\n            <a href=\"dashboard.php?page=class&id=<%= c.cid %>\" class=\"btn btn-sm btn-brand\">Open</a>\n            <a href=\"dashboard.php?page=grades&id=<%= c.cid %>\" class=\"btn btn-sm btn-outline-primary\">Grades</a>\n            <a href=\"dashboard.php?page=attendance&id=<%= c.cid %>\" class=\"btn btn-sm btn-outline-primary\">Attendance</a>\n            <a href=\"dashboard.php?page=settings&id=<%= c.cid %>\" class=\"btn btn-sm btn-outline-secondary\">Settings</a>\n            </div></div></div></div>\n        <% }); %>\n        </div>\n    <% } else { %>\n        <div class=\"card\"><div class=\"empty-state\"><div class=\"empty-icon\"><%- h.icon('school', 26) %></div><h6>No classes yet</h6><p>Create your first class to start recording grades.</p><a href=\"dashboard.php?page=create_class\" class=\"btn btn-accent\">+ New Class</a></div></div>\n    <% } %>\n\n    <% if (archived.length) { %>\n        <hr><h5 class=\"fw-bold text-muted mt-4\">Archived Classes</h5><div class=\"row g-2\">\n        <% archived.forEach((c) => { %>\n            <div class=\"col-md-3\"><div class=\"card shadow-sm\"><div class=\"card-body py-2\"><small class=\"text-muted\"><%= c.subject %> - <%= c.section %></small> <form method=\"POST\" class=\"d-inline float-end\"><input type=\"hidden\" name=\"action\" value=\"restore_class\"><input type=\"hidden\" name=\"class_id\" value=\"<%= Number(c.id) %>\"><button type=\"submit\" class=\"btn btn-sm btn-outline-secondary\">Restore</button></form></div></div></div>\n        <% }); %>\n        </div>\n    <% } %>\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n",
 "teacher/grades.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: 'School Portal' }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: 'grades', unread: 0, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <% if (!cls) { %>\n        <div class=\"alert alert-danger\">Class not found.</div>\n    <% } else if (no_terms) { %>\n        <div class=\"card\"><div class=\"empty-state\"><div class=\"empty-icon\"><%- h.icon('calendar', 26) %></div><h6>No terms set up</h6><p>This class is not linked to an academic year yet, so there is no term to grade.</p><a href=\"dashboard.php?page=settings&id=<%= class_id %>\" class=\"btn btn-accent\">Class settings</a></div></div>\n    <% } else { %>\n    <div class=\"page-header\">\n        <div>\n            <h4 class=\"page-title\">Term Grades</h4>\n            <p class=\"page-subtitle\">Enter the final Term Grade for each student.</p>\n        </div>\n        <a href=\"dashboard.php?page=class&id=<%= class_id %>\" class=\"btn btn-sm btn-outline-secondary\">Back to class</a>\n        <% if (Number(cls.is_advisory || 0) !== 0) { %>\n            <a href=\"dashboard.php?page=sf9&id=<%= class_id %>\" class=\"btn btn-sm btn-accent\">SF9 Report Cards</a>\n        <% } %>\n    </div>\n\n    <% // Term switcher: the DO 009 three-term year as a dropdown. A GET\n       // form so it still works without JavaScript; onchange submits it. %>\n    <form method=\"GET\" class=\"gb-term-picker\">\n        <input type=\"hidden\" name=\"page\" value=\"grades\">\n        <input type=\"hidden\" name=\"id\" value=\"<%= class_id %>\">\n        <label for=\"gbTermSelect\">Term</label>\n        <select name=\"term\" id=\"gbTermSelect\" class=\"form-select form-select-sm\" onchange=\"this.form.submit()\">\n            <% terms.forEach((t) => { const tid = Number(t.id); %>\n                <option value=\"<%= tid %>\" <%= tid === term_id ? 'selected' : '' %>>\n                    <%= t.label %><%= t.published ? ' (released)' : '' %>\n                </option>\n            <% }); %>\n        </select>\n    </form>\n\n    <div class=\"gb-head\">\n        <div class=\"gb-head-row\">\n            <div class=\"gb-head-main\">\n                <span class=\"gb-head-subject\"><%= cls.subject %></span>\n                <span class=\"gb-head-sep\">&middot;</span>\n                <span class=\"gb-head-section\"><%= cls.section %></span>\n                <span class=\"gb-head-sep\">&middot;</span>\n                <span class=\"gb-head-term\"><%= term_label %></span>\n            </div>\n            <% // Per-term cluster tag: labels which cluster THIS term's\n               // grades belong to. Saves against class_id + term_id only --\n               // it never changes the class itself. %>\n            <form method=\"POST\" class=\"gb-cluster-form\">\n                <%- csrf_field %>\n                <input type=\"hidden\" name=\"action\" value=\"set_term_cluster\">\n                <input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\">\n                <input type=\"hidden\" name=\"term_id\" value=\"<%= term_id %>\">\n                <label class=\"mb-0\" for=\"gbClusterSelect\">Cluster</label>\n                <select name=\"cluster_subject\" id=\"gbClusterSelect\" class=\"form-select form-select-sm\"\n                        onchange=\"this.form.submit()\"\n                        title=\"Label this term's grades with a cluster subject\">\n                    <option value=\"\" <%= term_tag ? '' : 'selected' %>>&mdash; set for <%= term_label %> &mdash;</option>\n                    <% Object.keys(clusters).forEach((name) => { const subs = clusters[name]; %>\n                        <optgroup label=\"<%= name %>\">\n                            <% if (subs.length) { %>\n                                <% subs.forEach((sub) => { %>\n                                    <option value=\"<%= sub %>\"\n                                            <%= term_tag && term_tag.subject === sub ? 'selected' : '' %>>\n                                        <%= sub %>\n                                    </option>\n                                <% }); %>\n                            <% } else { %>\n                                <option value=\"\" disabled>&mdash; coming soon &mdash;</option>\n                            <% } %>\n                        </optgroup>\n                    <% }); %>\n                </select>\n            </form>\n        </div>\n        <p class=\"gb-head-hint\">\n            Enter or press <kbd>&darr;</kbd> for the next student.\n            Grades save automatically.\n        </p>\n    </div>\n\n    <% if (progress.published) { %>\n        <div class=\"alert alert-success gb-notice\">\n            <strong><%= term_label %> is released.</strong>\n            Students can see these grades. Editing them re-publishes automatically.\n        </div>\n    <% } %>\n\n    <div class=\"gb-progress-wrap\" id=\"gbProgress\"\n         data-total=\"<%= Number(progress.total) %>\"\n         data-graded=\"<%= Number(progress.graded) %>\"\n         data-average=\"<%= (progress.average === null || progress.average === undefined) ? '' : String(progress.average) %>\"\n         data-descriptor=\"<%= String(progress.descriptor ?? '') %>\"\n         data-below=\"<%= Number(progress.below_passing) %>\"\n         data-published=\"<%= progress.published ? '1' : '0' %>\">\n        <div class=\"gb-progress\" role=\"progressbar\" aria-valuemin=\"0\" aria-valuemax=\"100\"\n             aria-valuenow=\"<%= progress.total ? Math.round(Number(progress.graded) / Number(progress.total) * 100) : 0 %>\"\n             aria-label=\"Grading progress\">\n            <div class=\"gb-progress-fill\" style=\"width:<%= progress.total ? Math.round(Number(progress.graded) / Number(progress.total) * 100) : 0 %>%\"></div>\n        </div>\n        <div class=\"gb-stats\">\n            <span class=\"gb-stat\" id=\"gbStatCount\">\n                <strong><%= Number(progress.graded) %></strong> of <strong><%= Number(progress.total) %></strong> students graded\n            </span>\n            <span class=\"gb-stat gb-stat-avg\">\n                Class average\n                <strong id=\"gbStatAvg\"><%- (progress.average === null || progress.average === undefined) ? '&mdash;' : h.esc(h.trim_num(progress.average)) %></strong>\n                <span class=\"gb-stat-desc\" id=\"gbStatDesc\"><%= String(progress.descriptor ?? '') %></span>\n            </span>\n            <% if (Number(progress.below_passing) > 0) { %>\n                <span class=\"gb-stat gb-stat-warn\" id=\"gbStatBelow\">\n                    <%= Number(progress.below_passing) %> below <%= Math.trunc(Number(passing_mark)) %>\n                </span>\n            <% } else { %>\n                <span class=\"gb-stat gb-stat-warn is-empty\" id=\"gbStatBelow\" hidden></span>\n            <% } %>\n        </div>\n    </div>\n\n    <% if (!roster.length) { %>\n        <div class=\"card\"><div class=\"empty-state\">\n            <div class=\"empty-icon\"><%- h.icon('users', 26) %></div>\n            <h6>No students enrolled</h6>\n            <p>Add students to this class before recording grades.</p>\n            <a href=\"dashboard.php?page=class&id=<%= class_id %>\" class=\"btn btn-accent\">Open class roster</a>\n        </div></div>\n    <% } else { %>\n        <form method=\"POST\" id=\"gradebookForm\" class=\"gb-form\">\n            <%- csrf_field %>\n            <input type=\"hidden\" name=\"action\" value=\"save_term_grades\">\n            <input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\">\n            <input type=\"hidden\" name=\"term_id\" value=\"<%= term_id %>\">\n\n            <div class=\"card gb-card\">\n                <table class=\"gb-table\" id=\"gradebookGrid\">\n                    <thead>\n                        <tr>\n                            <th class=\"gb-th gb-th-num\">Student No.</th>\n                            <th class=\"gb-th gb-th-name\">Name</th>\n                            <th class=\"gb-th gb-th-grade\">Term Grade</th>\n                            <th class=\"gb-th gb-th-desc\">Descriptor</th>\n                            <th class=\"gb-th gb-th-result\">Result</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                    <% roster.forEach((s) => {\n                        const sid = Number(s.user_id);\n                        const r = rows[sid] || { grade: null, descriptor: 'Not Graded', passed: false, stamp: null };\n                        const gval = (r.grade === null || r.grade === undefined) ? '' : h.trim_num(r.grade);\n                    %>\n                        <tr class=\"gb-row\" data-sid=\"<%= sid %>\" data-stamp=\"<%= r.stamp ?? '' %>\">\n                            <td class=\"gb-td gb-td-num\"><%= s.student_number %></td>\n                            <td class=\"gb-td gb-td-name\"><%= s.full_name %></td>\n                            <td class=\"gb-td gb-td-grade\">\n                                <input type=\"text\"\n                                       name=\"grade[<%= sid %>]\"\n                                       class=\"gb-input\"\n                                       inputmode=\"decimal\"\n                                       autocomplete=\"off\"\n                                       value=\"<%= gval %>\"\n                                       aria-label=\"Term Grade for <%= s.full_name %>\"\n                                       placeholder=\"&mdash;\">\n                                <% // Concurrency token for the no-JS form post. %>\n                                <input type=\"hidden\" name=\"stamp[<%= sid %>]\" value=\"<%= r.stamp ?? '' %>\">\n                            </td>\n                            <td class=\"gb-td gb-td-desc\"><span class=\"gb-desc\"><%= String(r.descriptor ?? '') %></span></td>\n                            <td class=\"gb-td gb-td-result\"><span class=\"gb-result\"><%- h.rc_result(r.passed, r.grade !== null && r.grade !== undefined) %></span></td>\n                        </tr>\n                    <% }); %>\n                        <tr class=\"gb-foot-row\">\n                            <td class=\"gb-td gb-td-num\">&mdash;</td>\n                            <td class=\"gb-td gb-td-name\">Class average</td>\n                            <td class=\"gb-td gb-td-grade\">\n                                <strong id=\"gbAvgCell\"><%- (averages.tg === null || averages.tg === undefined) ? '&mdash;' : h.esc(h.trim_num(averages.tg)) %></strong>\n                            </td>\n                            <td class=\"gb-td gb-td-desc\"><span class=\"gb-desc\" id=\"gbAvgDesc\"><%= String(progress.descriptor ?? '') %></span></td>\n                            <td class=\"gb-td gb-td-result\"><span class=\"gb-desc\"><%= Number(averages.n) %> graded</span></td>\n                        </tr>\n                    </tbody>\n                </table>\n            </div>\n\n            <div class=\"gb-save-bar\">\n                <span class=\"gb-save-status\" id=\"gbSaveStatus\" role=\"status\" aria-live=\"polite\"></span>\n                <% if (!progress.published) { %>\n                    <% // Always rendered (hidden when incomplete) so the JS can\n                       // reveal it the moment the last student is graded,\n                       // without a reload. The server still gates the POST. %>\n                    <button type=\"submit\" class=\"btn btn-accent<%= progress.complete ? '' : ' ms-auto' %>\"\n                            form=\"gbPublishForm\"<%= progress.complete ? '' : ' hidden' %>>\n                        Release <%= term_label %> to students\n                    </button>\n                <% } %>\n                <button type=\"submit\" class=\"btn btn-brand<%= (!progress.published && progress.complete) ? '' : ' ms-auto' %>\">Save</button>\n            </div>\n        </form>\n\n        <% // Kept OUTSIDE #gradebookForm: nesting a <form> inside another is\n           // invalid HTML and browsers silently drop the inner one, which\n           // breaks the enclosing Save button. The button reaches it via form=\"\". %>\n        <form method=\"POST\" id=\"gbPublishForm\" class=\"d-none\">\n            <%- csrf_field %>\n            <input type=\"hidden\" name=\"action\" value=\"publish_term\">\n            <input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\">\n            <input type=\"hidden\" name=\"term_id\" value=\"<%= term_id %>\">\n        </form>\n    <% } %>\n    <% } %>\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n",
 "teacher/settings.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: 'School Portal' }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: 'settings', unread: 0, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <% if (!cls) { %>\n        <div class=\"alert alert-danger\">Class not found.</div>\n    <% } else { %>\n    <div class=\"page-header\">\n        <div>\n            <a class=\"small d-inline-block mb-1\" href=\"dashboard.php?page=class&id=<%= class_id %>\">&larr; Back to Class</a>\n            <h4 class=\"page-title\">Settings: <%= cls.subject %></h4>\n            <p class=\"page-subtitle\"><%= cls.section %></p>\n        </div>\n    </div>\n\n    <div class=\"row g-3\">\n        <div class=\"col-md-6\">\n            <div class=\"card shadow-sm\">\n                <div class=\"card-header fw-semibold\">Class Information</div>\n                <div class=\"card-body\">\n                    <form method=\"POST\">\n                        <input type=\"hidden\" name=\"action\" value=\"update_class\">\n                        <input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\">\n                        <div class=\"mb-2\"><label class=\"small fw-semibold\">Subject</label><input type=\"text\" name=\"subject\" class=\"form-control\" value=\"<%= cls.subject %>\"></div>\n                        <div class=\"mb-2\"><label class=\"small fw-semibold\">Section</label><input type=\"text\" name=\"section\" class=\"form-control\" value=\"<%= cls.section %>\"></div>\n                        <div class=\"mb-2\"><label class=\"small fw-semibold\">School Year</label><input type=\"text\" name=\"school_year\" class=\"form-control\" value=\"<%= cls.school_year %>\"></div>\n                        <div class=\"mb-2\"><label class=\"small fw-semibold\">Description</label><textarea name=\"description\" class=\"form-control\" rows=\"2\"><%= cls.description ?? '' %></textarea></div>\n                        <div class=\"form-check mb-2\">\n                            <input class=\"form-check-input\" type=\"checkbox\" name=\"is_advisory\" id=\"isAdvisory\" value=\"1\" <%= Number(cls.is_advisory || 0) !== 0 ? 'checked' : '' %>>\n                            <label class=\"form-check-label small\" for=\"isAdvisory\">\n                                This is my <strong>advisory class</strong>\n                            </label>\n                            <small class=\"text-muted d-block\">The advisory class's teacher is the section adviser - the only one who can generate the students' SF9 report cards. The admin panel can also reassign this.</small>\n                        </div>\n                        <button type=\"submit\" class=\"btn btn-sm btn-brand\">Update</button>\n                    </form>\n                </div>\n            </div>\n        </div>\n        <div class=\"col-md-6\">\n            <div class=\"card shadow-sm\">\n                <div class=\"card-header fw-semibold\">Join Code</div>\n                <div class=\"card-body\">\n                    <p class=\"mb-1\">Current code: <strong><%- cls.join_code ? h.esc(cls.join_code) : '<span class=\"text-muted\">Disabled</span>' %></strong></p>\n                    <div class=\"d-flex gap-1\">\n                        <form method=\"POST\"><input type=\"hidden\" name=\"action\" value=\"new_code\"><input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\"><button type=\"submit\" class=\"btn btn-sm btn-outline-primary\">Generate New</button></form>\n                        <% if (cls.join_code) { %>\n                            <form method=\"POST\"><input type=\"hidden\" name=\"action\" value=\"disable_join\"><input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\"><button type=\"submit\" class=\"btn btn-sm btn-outline-warning\">Disable</button></form>\n                        <% } %>\n                    </div>\n                </div>\n            </div>\n\n            <div class=\"card shadow-sm mt-3\">\n                <div class=\"card-header fw-semibold\">Grading Scale</div>\n                <div class=\"card-body\">\n                    <p class=\"small text-muted mb-2\">\n                        Grades are entered directly and labelled using the DepEd Order No. 015,\n                        s. 2026 reporting scale.\n                    </p>\n                    <table class=\"table table-sm mb-0 gb-scale-table\">\n                        <tbody>\n                        <% bands.forEach((b) => { %>\n                            <tr>\n                                <td class=\"gb-scale-range\"><%= h.trim_num(b.min_grade) %>&ndash;<%= h.trim_num(b.max_grade) %></td>\n                                <td><%= b.label_en %></td>\n                                <td class=\"text-muted small\"><%= b.label_fil ?? '' %></td>\n                            </tr>\n                        <% }); %>\n                        </tbody>\n                    </table>\n                    <p class=\"small text-muted mb-0 mt-2\">\n                        Passing mark: <strong><%= Math.trunc(Number(passing_mark)) %></strong>\n                    </p>\n                </div>\n            </div>\n\n            <div class=\"card shadow-sm mt-3\">\n                <div class=\"card-header fw-semibold\">Active Term</div>\n                <div class=\"card-body\">\n                    <form method=\"POST\">\n                        <input type=\"hidden\" name=\"action\" value=\"set_term\">\n                        <input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\">\n                        <div class=\"mb-2\">\n                            <select name=\"term_id\" class=\"form-select\">\n                                <option value=\"\">None</option>\n                                <% terms.forEach((t) => { %>\n                                    <option value=\"<%= Number(t.id) %>\" <%= Number(cls.current_term_id) === Number(t.id) ? 'selected' : '' %>><%= t.label %></option>\n                                <% }); %>\n                            </select>\n                        </div>\n                        <button type=\"submit\" class=\"btn btn-sm btn-brand\">Set Active Term</button>\n                    </form>\n                </div>\n            </div>\n\n            <div class=\"card shadow-sm mt-3 border-danger\">\n                <div class=\"card-header fw-semibold text-danger\">Danger Zone</div>\n                <div class=\"card-body\">\n                    <form method=\"POST\" style=\"display:inline;\"><input type=\"hidden\" name=\"action\" value=\"archive_class\"><input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\"><button type=\"submit\" class=\"btn btn-sm btn-outline-warning\" onclick=\"return confirm('Archive this class?')\">Archive</button></form>\n                    <form method=\"POST\" style=\"display:inline;\"><input type=\"hidden\" name=\"action\" value=\"delete_class\"><input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\"><button type=\"submit\" class=\"btn btn-sm btn-outline-danger\" onclick=\"return confirm('DELETE this class permanently? This cannot be undone.')\">Delete</button></form>\n                </div>\n            </div>\n        </div>\n    </div>\n    <% } %>\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n",
 "teacher/sf9.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: 'School Portal' }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: 'sf9', unread: 0, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <% if (!cls) { %>\n        <div class=\"alert alert-danger\">Class not found.</div>\n    <% } else if (error === 'advisory') { %>\n        <div class=\"alert alert-danger\">SF9 report cards are generated by the section adviser only. This is not your advisory class.</div>\n    <% } else if (error === 'no_year') { %>\n        <div class=\"alert alert-warning\">Link this class to an academic year first (Settings) to print SF9s.</div>\n    <% } else { %>\n    <div class=\"page-header\">\n        <div>\n            <a class=\"small d-inline-block mb-1\" href=\"dashboard.php?page=grades&id=<%= class_id %>\">&larr; Back to Grades</a>\n            <h4 class=\"page-title\">SF9 Report Cards</h4>\n            <p class=\"page-subtitle\"><%= cls.subject %> &middot; <%= cls.section %> &middot; SY <%= cls.year_label ?? '' %></p>\n        </div>\n    </div>\n    <div class=\"alert alert-info small\">\n        Each download fills the official SF9 template with the student's <strong>released</strong> Term Grades,\n        final grade per subject, remarks and the general average - ready to print. Unreleased terms stay blank.\n    </div>\n\n    <% if (!roster.length) { %>\n        <div class=\"alert alert-info\">No students enrolled.</div>\n    <% } else { %>\n        <div class=\"card shadow-sm\">\n            <div class=\"table-responsive\">\n                <table class=\"table table-hover align-middle mb-0\">\n                    <thead><tr><th>Student No.</th><th>Name</th><th class=\"text-end\">SF9</th></tr></thead>\n                    <tbody>\n                    <% roster.forEach((s) => { %>\n                        <tr>\n                            <td><%= s.student_number %></td>\n                            <td><%= s.full_name %></td>\n                            <td class=\"text-end\">\n                                <form method=\"POST\" class=\"d-inline\">\n                                    <%- csrf_field %>\n                                    <input type=\"hidden\" name=\"action\" value=\"export_sf9\">\n                                    <input type=\"hidden\" name=\"class_id\" value=\"<%= class_id %>\">\n                                    <input type=\"hidden\" name=\"student_id\" value=\"<%= Number(s.id) %>\">\n                                    <button type=\"submit\" class=\"btn btn-sm btn-brand\">Download SF9</button>\n                                </form>\n                            </td>\n                        </tr>\n                    <% }); %>\n                    </tbody>\n                </table>\n            </div>\n        </div>\n    <% } %>\n    <% } %>\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n",
 "teacher/submissions.ejs": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <%- include('../partials/app_head', { title: 'School Portal' }) %>\n</head>\n<body>\n\n<%- include('../partials/navbar', { page: 'submissions', unread: 0, chip_role: chip_role, chip_ini: chip_ini }) %>\n\n<div class=\"container mt-4\">\n    <% if (flash) { %>\n        <div class=\"alert alert-<%= flash_type %> alert-dismissible fade show\" role=\"alert\"><%= flash %><button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\"></button></div>\n    <% } %>\n\n    <% if (!assign) { %>\n        <div class=\"alert alert-danger\">Assignment not found.</div>\n    <% } else { %>\n    <div class=\"page-header\">\n        <div>\n            <a class=\"small d-inline-block mb-1\" href=\"dashboard.php?page=class&id=<%= Number(assign.class_id) %>&tab=assignments\">&larr; Back to Assignments</a>\n            <h4 class=\"page-title\"><%= assign.title %></h4>\n            <p class=\"page-subtitle\"><%= assign.subject %> &middot; <%= assign.section %><% if (Number(assign.requires_file || 0) !== 0) { %> &middot; File submission required<% } %></p>\n        </div>\n        <div class=\"d-flex gap-2\">\n            <form method=\"POST\" style=\"display:inline;\">\n                <input type=\"hidden\" name=\"action\" value=\"download_all_submissions\">\n                <input type=\"hidden\" name=\"assignment_id\" value=\"<%= assignment_id %>\">\n                <button type=\"submit\" class=\"btn btn-sm btn-outline-success\">Download all (.zip)</button>\n            </form>\n        </div>\n    </div>\n\n    <% if (!subs.length) { %>\n        <div class=\"alert alert-info\">No submissions yet.</div>\n    <% } else { %>\n    <div class=\"table-responsive\">\n        <table class=\"table table-hover\">\n            <thead><tr><th>Student</th><th>Submitted</th><th>File</th><th>Score</th><th>Feedback</th><th></th></tr></thead>\n            <tbody>\n            <% subs.forEach((sub) => { const form_id = 'gradeform_' + Number(sub.id); %>\n                <tr>\n                    <td><%= sub.full_name %><% if (Number(sub.is_late || 0) !== 0) { %> <span class=\"badge bg-warning text-dark\">Late</span><% } %></td>\n                    <td><small><%- sub.submitted_at %></small></td>\n                    <td><% if (sub.file_url) { %><a href=\"download.php?f=<%= encodeURIComponent(sub.file_url) %>\" target=\"_blank\" class=\"small\"><%= sub.original_name || 'View File' %></a><% } else { %><span class=\"text-muted small\">No file</span><% } %></td>\n                    <td><input type=\"number\" step=\"0.01\" name=\"score\" form=\"<%= form_id %>\" class=\"form-control form-control-sm\" style=\"width:70px;\" value=\"<%= sub.score ?? '' %>\"></td>\n                    <td><input type=\"text\" name=\"feedback\" form=\"<%= form_id %>\" class=\"form-control form-control-sm\" style=\"width:150px;\" value=\"<%= sub.feedback ?? '' %>\"></td>\n                    <td><button type=\"submit\" form=\"<%= form_id %>\" class=\"btn btn-sm btn-success\">Grade</button></td>\n                </tr>\n            <% }); %>\n            </tbody>\n        </table>\n    </div>\n    <% subs.forEach((sub) => { %>\n        <form method=\"POST\" id=\"gradeform_<%= Number(sub.id) %>\" class=\"d-none\">\n            <input type=\"hidden\" name=\"action\" value=\"grade_submission\">\n            <input type=\"hidden\" name=\"submission_id\" value=\"<%= Number(sub.id) %>\">\n        </form>\n    <% }); %>\n    <% } %>\n\n    <% if (typeof missing !== 'undefined' && missing && missing.length) { %>\n        <div class=\"card mt-3\"><div class=\"card-header\">Not yet submitted (<%= missing.length %>)</div><div class=\"card-body py-2\">\n        <% missing.forEach((m) => { %>\n            <span class=\"badge bg-light text-dark border me-1 mb-1\"><%= m.full_name %></span>\n        <% }); %>\n        </div></div>\n    <% } %>\n    <% } %>\n</div>\n\n<%- include('../partials/footer') %>\n</body>\n</html>\n"
};
